-- 4. Questions -------------------------------------------------------------
INSERT INTO public.quiz_questions (id, quiz_id, question, kind, options, correct_index, explanation, position)
SELECT v.id, v.quiz_id, v.question, v.kind, v.options, v.correct_index, v.explanation, v.position
  FROM (VALUES
    ('909a8c64-c2ec-533a-a843-04f84a2fedab'::uuid, '22e3e5e3-08f5-52af-8feb-18eb2f538c34'::uuid, 'Quel âge a le système solaire ?', 'mcq', '["Environ 4,6 milliards d’années","Environ 4,6 millions d’années","Environ 13,8 milliards d’années","Environ 500 millions d’années"]'::jsonb, 0, 'Il s’est formé à partir d’un nuage de gaz et de poussières.', 1),
    ('351824b0-aa79-59c5-9b58-0b1ef5c6bc46'::uuid, '22e3e5e3-08f5-52af-8feb-18eb2f538c34'::uuid, 'Quelles sont les quatre planètes telluriques ?', 'mcq', '["Mercure, Vénus, la Terre, Mars","Jupiter, Saturne, Uranus, Neptune","La Terre, Mars, Jupiter, Saturne","Mercure, la Terre, Jupiter, Pluton"]'::jsonb, 0, 'Elles sont rocheuses, denses et proches du Soleil.', 2),
    ('d9b39f48-2826-550b-bb9d-e8202ce7bffa'::uuid, '22e3e5e3-08f5-52af-8feb-18eb2f538c34'::uuid, 'Qu’est-ce qui provoque l’alternance du jour et de la nuit ?', 'mcq', '["La rotation de la Terre sur elle-même en 24 heures","La révolution autour du Soleil","L’inclinaison de l’axe","Le mouvement de la Lune"]'::jsonb, 0, 'La révolution, elle, dure 365,25 jours.', 3),
    ('b0596eba-9cb0-5e8f-a728-f45e9d9c3a24'::uuid, '22e3e5e3-08f5-52af-8feb-18eb2f538c34'::uuid, 'Qu’est-ce qui explique les saisons ?', 'mcq', '["L’inclinaison de 23,5° de l’axe de rotation","La distance variable au Soleil","La rotation de la Lune","Les variations de l’activité solaire"]'::jsonb, 0, 'Les rayons arrivent plus ou moins à la verticale selon la période.', 4),
    ('ababb471-a03c-5f41-81ef-e68ec7cde227'::uuid, '22e3e5e3-08f5-52af-8feb-18eb2f538c34'::uuid, 'Pourquoi l’eau peut-elle être liquide sur Terre ?', 'mcq', '["Grâce à sa distance au Soleil","Grâce à son champ magnétique","Grâce à la Lune","Grâce à sa vitesse de rotation"]'::jsonb, 0, 'Trop près, elle s’évaporerait ; trop loin, elle gèlerait.', 5),
    ('427cdd7a-b0d2-5bb8-a497-591636930a58'::uuid, '22e3e5e3-08f5-52af-8feb-18eb2f538c34'::uuid, 'Quelle serait la température moyenne terrestre sans effet de serre naturel ?', 'mcq', '["Environ −18 °C","Environ 0 °C","Environ +40 °C","Environ −60 °C"]'::jsonb, 0, 'Elle est en réalité d’environ +15 °C.', 6),
    ('04f1d9e0-074d-5381-984b-cc36a6e73b1d'::uuid, '22e3e5e3-08f5-52af-8feb-18eb2f538c34'::uuid, 'Quel gaz atmosphérique filtre une grande partie des ultraviolets ?', 'mcq', '["L’ozone","Le dioxyde de carbone","L’azote","Le méthane"]'::jsonb, 0, 'Il forme une couche dans la stratosphère.', 7),
    ('9754fdcb-81dd-5ba4-9918-e602009c6730'::uuid, '22e3e5e3-08f5-52af-8feb-18eb2f538c34'::uuid, 'La Terre est âgée d’environ 4,54 milliards d’années.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'La datation repose notamment sur la radioactivité des roches.', 8),
    ('3d1a9f76-4033-5a1c-9a41-e6e5fce3e317'::uuid, '6779051d-0c68-5083-a994-404c5cc2fcd7'::uuid, 'De quoi est faite la lithosphère ?', 'mcq', '["De la croûte et de la partie supérieure rigide du manteau","Du noyau et du manteau","De la croûte uniquement","De l’asthénosphère uniquement"]'::jsonb, 0, 'Elle repose sur l’asthénosphère, plus ductile.', 1),
    ('3bda7558-d232-5ba6-aafa-89f766333d3d'::uuid, '6779051d-0c68-5083-a994-404c5cc2fcd7'::uuid, 'À quelle vitesse les plaques se déplacent-elles ?', 'mcq', '["Quelques centimètres par an","Quelques mètres par an","Quelques millimètres par siècle","Quelques kilomètres par an"]'::jsonb, 0, 'C’est l’ordre de grandeur de la croissance des ongles.', 2),
    ('4c9c6eea-bf02-5d2b-b275-a8cce2c758c4'::uuid, '6779051d-0c68-5083-a994-404c5cc2fcd7'::uuid, 'Qui propose la dérive des continents en 1912 ?', 'mcq', '["Alfred Wegener","Charles Darwin","Louis Pasteur","Charles Richter"]'::jsonb, 0, 'Son idée est rejetée faute de moteur explicatif.', 3),
    ('ade48629-0e93-5286-aeab-251f2f0627df'::uuid, '6779051d-0c68-5083-a994-404c5cc2fcd7'::uuid, 'Que se passe-t-il au niveau d’une dorsale océanique ?', 'mcq', '["Deux plaques s’écartent et de la lithosphère neuve se forme","Une plaque plonge sous une autre","Deux plaques glissent latéralement","Deux continents entrent en collision"]'::jsonb, 0, 'C’est une frontière divergente.', 4),
    ('d2d8d1c9-76d2-5469-9519-9f990acac3c6'::uuid, '6779051d-0c68-5083-a994-404c5cc2fcd7'::uuid, 'Qu’est-ce qu’une zone de subduction ?', 'mcq', '["Une zone où une plaque océanique plonge sous une autre plaque","Une zone où deux plaques s’écartent","Une zone sans activité sismique","Une zone de faille transformante"]'::jsonb, 0, 'Elle s’accompagne de fosses, de séismes profonds et de volcanisme explosif.', 5),
    ('c1093551-23a9-55fd-ac90-7f9370c4f215'::uuid, '6779051d-0c68-5083-a994-404c5cc2fcd7'::uuid, 'Que produit la collision de deux plaques continentales ?', 'mcq', '["Une chaîne de montagnes","Une fosse océanique","Une dorsale","Un point chaud"]'::jsonb, 0, 'L’Himalaya en est l’exemple actuel.', 6),
    ('fe90c2c4-bd13-594f-adcb-84ae073268d2'::uuid, '6779051d-0c68-5083-a994-404c5cc2fcd7'::uuid, 'Quel phénomène met le manteau en mouvement ?', 'mcq', '["La convection due à la chaleur interne","Le vent solaire","La rotation de la Lune","Les marées océaniques"]'::jsonb, 0, 'La traction de la plaque plongeante y contribue également.', 7),
    ('e5155db6-bec0-5079-b19c-d42950e24ccd'::uuid, '6779051d-0c68-5083-a994-404c5cc2fcd7'::uuid, 'La surface de la Terre se recycle : ce qui naît aux dorsales disparaît en subduction.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'La surface totale du globe reste ainsi constante.', 8),
    ('722e92db-4caf-5e95-b040-4b77c91ce9af'::uuid, 'eb01042e-95d7-5a33-bae4-1facf14fdbad'::uuid, 'Quelle est la cause d’un séisme ?', 'mcq', '["La rupture brutale de roches le long d’une faille","Une éruption volcanique systématique","Le passage d’une comète","Le réchauffement de l’atmosphère"]'::jsonb, 0, 'Les roches accumulent de l’énergie avant de casser.', 1),
    ('fe1fc137-4442-5658-aa19-e030e363ad6d'::uuid, 'eb01042e-95d7-5a33-bae4-1facf14fdbad'::uuid, 'Comment appelle-t-on le point de rupture en profondeur ?', 'mcq', '["Le foyer","L’épicentre","La faille","La dorsale"]'::jsonb, 0, 'L’épicentre est le point situé à sa verticale en surface.', 2),
    ('b4d0664c-0bdb-5ce7-be27-cd2ae1455e84'::uuid, 'eb01042e-95d7-5a33-bae4-1facf14fdbad'::uuid, 'Que mesure la magnitude ?', 'mcq', '["L’énergie libérée par le séisme","Les dégâts observés en un lieu","La profondeur du foyer","La durée de la secousse"]'::jsonb, 0, 'Il n’y a qu’une seule magnitude par séisme.', 3),
    ('58abaa90-a424-52ed-8102-ede0825b5f2a'::uuid, 'eb01042e-95d7-5a33-bae4-1facf14fdbad'::uuid, 'Que mesure l’intensité ?', 'mcq', '["Les effets ressentis et observés en un lieu donné","L’énergie totale libérée","La vitesse des ondes","La longueur de la faille"]'::jsonb, 0, 'Elle varie d’un endroit à l’autre pour un même séisme.', 4),
    ('3bb9ca98-cbc8-5b9b-a9e3-0905bef12b5c'::uuid, 'eb01042e-95d7-5a33-bae4-1facf14fdbad'::uuid, 'Que représente une augmentation de 1 sur l’échelle de magnitude ?', 'mcq', '["Environ 30 fois plus d’énergie libérée","Deux fois plus d’énergie","Dix fois plus de victimes","Une secousse deux fois plus longue"]'::jsonb, 0, 'L’échelle est logarithmique.', 5),
    ('5c1b23f9-7f57-5feb-8152-c3641076c4f0'::uuid, 'eb01042e-95d7-5a33-bae4-1facf14fdbad'::uuid, 'Comment définit-on le risque sismique ?', 'mcq', '["Le croisement d’un aléa et d’une vulnérabilité","La magnitude du dernier séisme","Le nombre de failles actives","La profondeur moyenne des foyers"]'::jsonb, 0, 'On agit sur la vulnérabilité, pas sur l’aléa.', 6),
    ('bfd69aa7-7488-5011-8d15-93e87fe4bbb7'::uuid, 'eb01042e-95d7-5a33-bae4-1facf14fdbad'::uuid, 'Quelle mesure réduit efficacement les dégâts d’un séisme ?', 'mcq', '["Les normes parasismiques de construction","La prédiction exacte de la date","L’interdiction des sismographes","Le comblement des failles"]'::jsonb, 0, 'On ne sait pas prédire la date d’un séisme.', 7),
    ('9229b8a2-b7cf-5852-84c1-36fd061e4e44'::uuid, 'eb01042e-95d7-5a33-bae4-1facf14fdbad'::uuid, 'Un séisme sous-marin peut déclencher un tsunami.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Le déplacement du fond met en mouvement toute la colonne d’eau.', 8),
    ('7ee8ff8f-4f59-5e3d-bae3-4328b0f57931'::uuid, '8aa87cbb-4f59-5da2-a550-2204916b2568'::uuid, 'Qu’est-ce que le magma ?', 'mcq', '["De la roche fondue formée en profondeur","De la lave refroidie en surface","Un mélange de cendres et d’eau","Un gaz volcanique"]'::jsonb, 0, 'On parle de lave une fois qu’il est sorti.', 1),
    ('02f872c2-9027-551b-9b09-081eb1d2c54c'::uuid, '8aa87cbb-4f59-5da2-a550-2204916b2568'::uuid, 'Qu’est-ce qui détermine le type d’éruption ?', 'mcq', '["La viscosité du magma et sa teneur en gaz","La hauteur du volcan","La saison","La proximité de la mer"]'::jsonb, 0, 'Un magma visqueux retient les gaz jusqu’à l’explosion.', 2),
    ('8a4ef7d4-d186-5118-ba67-9503e1018000'::uuid, '8aa87cbb-4f59-5da2-a550-2204916b2568'::uuid, 'Quel type d’éruption produit des coulées de lave ?', 'mcq', '["L’éruption effusive","L’éruption explosive","L’éruption phréatique","Aucune"]'::jsonb, 0, 'Le magma fluide laisse les gaz s’échapper.', 3),
    ('6f8fcc1c-de14-55f6-8bb4-50bf92478584'::uuid, '8aa87cbb-4f59-5da2-a550-2204916b2568'::uuid, 'Qu’est-ce qu’une nuée ardente ?', 'mcq', '["Un mélange brûlant de gaz et de particules qui dévale les pentes","Une coulée de lave lente","Un nuage de vapeur d’eau","Une pluie de cendres froides"]'::jsonb, 0, 'Elle progresse à plusieurs centaines de kilomètres par heure.', 4),
    ('617e0b1c-acb9-54c8-9d1f-0c1e47e15f23'::uuid, '8aa87cbb-4f59-5da2-a550-2204916b2568'::uuid, 'Où se situe le volcanisme explosif ?', 'mcq', '["Dans les zones de subduction","Aux dorsales océaniques","Uniquement aux points chauds","Au centre des continents stables"]'::jsonb, 0, 'La ceinture de feu du Pacifique en est l’exemple.', 5),
    ('5f6a96d0-c882-585f-bb4f-e19631552049'::uuid, '8aa87cbb-4f59-5da2-a550-2204916b2568'::uuid, 'Qu’est-ce qu’un point chaud ?', 'mcq', '["Une remontée de magma indépendante des frontières de plaques","Une zone de collision continentale","Une faille transformante","Une fosse océanique"]'::jsonb, 0, 'Hawaï et La Réunion en sont des exemples.', 6),
    ('cce6f25b-f406-5244-affc-dac7094cc657'::uuid, '8aa87cbb-4f59-5da2-a550-2204916b2568'::uuid, 'Quel signe annonce souvent une éruption ?', 'mcq', '["Le gonflement de l’édifice volcanique","Une baisse de la température du sol","L’arrêt de toute activité sismique","Une hausse du niveau de la mer"]'::jsonb, 0, 'GPS et inclinomètres le mesurent en continu.', 7),
    ('619bc56e-6912-584d-8239-cd2110f51b6a'::uuid, '8aa87cbb-4f59-5da2-a550-2204916b2568'::uuid, 'Contrairement aux séismes, les éruptions sont souvent précédées de signes détectables.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est ce qui rend l’évacuation possible, comme au Pinatubo en 1991.', 8),
    ('0554a3ca-ce43-5e43-bcca-8626e3d5c4a0'::uuid, '332bdaee-985e-5f18-aa36-a3c5f1031626'::uuid, 'Pourquoi l’équateur reçoit-il plus d’énergie solaire que les pôles ?', 'mcq', '["Les rayons y arrivent presque à la verticale","L’équateur est plus proche du Soleil","L’atmosphère y est absente","Le sol y est plus sombre"]'::jsonb, 0, 'Aux pôles, la même énergie se répartit sur une plus grande surface.', 1),
    ('922403b5-2630-53d2-ac20-ee4fda47655a'::uuid, '332bdaee-985e-5f18-aa36-a3c5f1031626'::uuid, 'Qu’est-ce qu’une dépression ?', 'mcq', '["Une zone de basse pression où l’air s’élève","Une zone de haute pression où l’air descend","Un courant océanique froid","Une masse d’air sèche"]'::jsonb, 0, 'L’air chaud, moins dense, monte.', 2),
    ('6aedad4b-a275-5b9b-8303-d3a7d775ea66'::uuid, '332bdaee-985e-5f18-aa36-a3c5f1031626'::uuid, 'Qu’est-ce que le vent ?', 'mcq', '["De l’air qui se déplace de la haute vers la basse pression","Un mouvement vertical de l’océan","Une variation de température du sol","Un phénomène lié aux marées"]'::jsonb, 0, 'La force de Coriolis dévie ensuite ce déplacement.', 3),
    ('a969cd46-2fd5-5c62-9271-8bcf5ce939c9'::uuid, '332bdaee-985e-5f18-aa36-a3c5f1031626'::uuid, 'Quelle différence entre météo et climat ?', 'mcq', '["La météo décrit quelques jours, le climat des moyennes sur au moins trente ans","La météo concerne l’océan, le climat l’atmosphère","La météo est mondiale, le climat local","Il n’y a aucune différence"]'::jsonb, 0, 'Confondre les deux est l’erreur la plus fréquente.', 4),
    ('eb76cca7-f2df-5cd2-9783-63eb714cb50b'::uuid, '332bdaee-985e-5f18-aa36-a3c5f1031626'::uuid, 'Quel courant chaud adoucit le climat de l’Europe de l’Ouest ?', 'mcq', '["Le Gulf Stream","Le courant de Humboldt","Le courant du Labrador","Le courant circumpolaire"]'::jsonb, 0, 'Il transporte de l’eau chaude vers l’Atlantique nord.', 5),
    ('3e4cd7bd-8a52-5a7d-9396-3bc712f06032'::uuid, '332bdaee-985e-5f18-aa36-a3c5f1031626'::uuid, 'Qu’est-ce que la circulation thermohaline ?', 'mcq', '["Une circulation profonde liée à la température et à la salinité","Un vent d’altitude","Un courant de surface entraîné par les vents","Un cycle des saisons"]'::jsonb, 0, 'Son parcours complet dure environ mille ans.', 6),
    ('1e1dd2a4-88d4-5622-80e5-8fe0b7776e10'::uuid, '332bdaee-985e-5f18-aa36-a3c5f1031626'::uuid, 'À quelle condition de température océanique naissent les cyclones tropicaux ?', 'mcq', '["Au-dessus de 26 °C","Au-dessus de 15 °C","En dessous de 10 °C","La température n’intervient pas"]'::jsonb, 0, 'L’évaporation intense fournit leur énergie.', 7),
    ('408084fa-0358-578d-9f0e-ff62aff6ff3d'::uuid, '332bdaee-985e-5f18-aa36-a3c5f1031626'::uuid, 'La prévision météorologique détaillée devient impossible au-delà d’environ deux semaines.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'L’atmosphère est un système chaotique.', 8),
    ('e2d4bf73-73e5-5ceb-9680-da081fd053f8'::uuid, '2400222c-391d-5f7c-bc25-3506a0003d42'::uuid, 'Quelle est la cause principale du réchauffement climatique actuel ?', 'mcq', '["Les émissions humaines de gaz à effet de serre","Les variations de l’orbite terrestre","L’activité volcanique récente","La fonte naturelle des glaciers"]'::jsonb, 0, 'CO₂, méthane et protoxyde d’azote en sont les principaux.', 1),
    ('bd6354a0-51f1-512f-ad3a-fb92e046f3b8'::uuid, '2400222c-391d-5f7c-bc25-3506a0003d42'::uuid, 'De combien la température moyenne mondiale a-t-elle augmenté depuis l’ère industrielle ?', 'mcq', '["Environ 1,1 à 1,2 °C","Environ 5 °C","Environ 0,1 °C","Environ 3 °C"]'::jsonb, 0, 'C’est la vitesse de ce réchauffement qui est inédite.', 2),
    ('8bba7ea0-6344-55a2-a4d3-0e20a9976b11'::uuid, '2400222c-391d-5f7c-bc25-3506a0003d42'::uuid, 'Comment connaît-on la teneur en CO₂ de l’atmosphère il y a 800 000 ans ?', 'mcq', '["Grâce aux bulles d’air piégées dans les carottes de glace","Grâce aux relevés météorologiques anciens","Grâce aux textes historiques","Grâce aux satellites"]'::jsonb, 0, 'Groenland et Antarctique conservent ces archives.', 3),
    ('7e19e62c-013a-5175-b882-7b6e615a6d4f'::uuid, '2400222c-391d-5f7c-bc25-3506a0003d42'::uuid, 'Qu’est-ce que l’effet de serre ?', 'mcq', '["Des gaz retiennent une partie du rayonnement infrarouge renvoyé par le sol","Une couche qui bloque le rayonnement solaire","Un phénomène uniquement urbain","Un effet du champ magnétique"]'::jsonb, 0, 'Naturel, il rend la Terre habitable ; renforcé, il la réchauffe.', 4),
    ('126b8e13-e06e-50ab-9cbc-50db18d6d1b4'::uuid, '2400222c-391d-5f7c-bc25-3506a0003d42'::uuid, 'Quelles causes expliquent la hausse du niveau des mers ?', 'mcq', '["La dilatation de l’eau et la fonte des glaciers et calottes","La fonte de la banquise flottante uniquement","L’augmentation des précipitations","L’acidification des océans"]'::jsonb, 0, 'La banquise, déjà flottante, ne fait pas monter le niveau en fondant.', 5),
    ('064bcd32-462b-5ae3-9a4d-7e6fe4a59980'::uuid, '2400222c-391d-5f7c-bc25-3506a0003d42'::uuid, 'Qu’est-ce que l’acidification des océans ?', 'mcq', '["La baisse du pH due à la dissolution du CO₂","Le rejet d’acides industriels","La hausse de la salinité","Le réchauffement des eaux de surface"]'::jsonb, 0, 'Elle fragilise les organismes à coquille et les coraux.', 6),
    ('b4b7dfb5-0a14-5e0a-a9d6-768b70958359'::uuid, '2400222c-391d-5f7c-bc25-3506a0003d42'::uuid, 'Quelle différence entre atténuation et adaptation ?', 'mcq', '["L’atténuation réduit les émissions, l’adaptation réduit la vulnérabilité","L’atténuation est locale, l’adaptation mondiale","L’atténuation concerne l’eau, l’adaptation l’air","Les deux mots sont synonymes"]'::jsonb, 0, 'Les deux stratégies sont complémentaires.', 7),
    ('9e6d34ea-e7d0-584a-a843-74c5a2a851b7'::uuid, '2400222c-391d-5f7c-bc25-3506a0003d42'::uuid, 'L’accord de Paris de 2015 vise à contenir le réchauffement nettement en dessous de 2 °C.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Avec l’ambition de le limiter à 1,5 °C.', 8),
    ('a24033b3-52d3-51d5-988a-1cecc1636c9e'::uuid, '63aaf518-1dc8-57bc-9c69-3b188f8f36d7'::uuid, 'Quelle part de l’eau de la planète est salée ?', 'mcq', '["Environ 97,5 %","Environ 70 %","Environ 50 %","Environ 30 %"]'::jsonb, 0, 'L’eau douce accessible représente moins de 1 % du total.', 1),
    ('e0c0ecf8-3a1f-523c-80ee-608c60408aa4'::uuid, '63aaf518-1dc8-57bc-9c69-3b188f8f36d7'::uuid, 'Qu’est-ce qu’une nappe phréatique ?', 'mcq', '["Une réserve d’eau souterraine alimentée par l’infiltration","Un lac artificiel de barrage","Une couche de glace continentale","Un bras de rivière souterrain unique"]'::jsonb, 0, 'Elle se recharge lentement par les précipitations.', 2),
    ('4443ebf2-f8af-5e11-814a-140ff27b46df'::uuid, '63aaf518-1dc8-57bc-9c69-3b188f8f36d7'::uuid, 'Quel secteur consomme le plus d’eau dans le monde ?', 'mcq', '["L’agriculture, avec environ 70 % des prélèvements","L’industrie","Les usages domestiques","La production d’électricité"]'::jsonb, 0, 'L’irrigation en représente l’essentiel.', 3),
    ('22ce806b-3636-59ae-b40d-8cf6ac9cb756'::uuid, '63aaf518-1dc8-57bc-9c69-3b188f8f36d7'::uuid, 'Qu’est-ce que l’eau virtuelle ?', 'mcq', '["L’eau nécessaire à la production d’un bien","L’eau des nappes profondes","L’eau de pluie non captée","L’eau perdue par évaporation"]'::jsonb, 0, 'Environ 15 000 litres pour un kilo de bœuf.', 4),
    ('e1bd883c-c3bd-5869-b700-0a8362d6678e'::uuid, '63aaf518-1dc8-57bc-9c69-3b188f8f36d7'::uuid, 'Quelle étape termine la potabilisation de l’eau ?', 'mcq', '["La désinfection au chlore ou à l’ozone","La floculation","Le dégrillage","La décantation"]'::jsonb, 0, 'Elle élimine les micro-organismes restants.', 5),
    ('dde197f6-35ab-52f6-8d7a-29615d2a4c89'::uuid, '63aaf518-1dc8-57bc-9c69-3b188f8f36d7'::uuid, 'À quoi sert une station d’épuration ?', 'mcq', '["À traiter les eaux usées avant leur rejet dans le milieu","À rendre l’eau potable","À dessaler l’eau de mer","À stocker l’eau de pluie"]'::jsonb, 0, 'Le traitement est mécanique puis biologique.', 6),
    ('edf601e0-a12d-5f40-bdfa-d4f68a57b647'::uuid, '63aaf518-1dc8-57bc-9c69-3b188f8f36d7'::uuid, 'Qu’appelle-t-on surexploitation d’une nappe ?', 'mcq', '["Un prélèvement plus rapide que sa recharge naturelle","Une pollution par les nitrates","Un captage interdit","Une baisse de la pluviométrie"]'::jsonb, 0, 'Le niveau de la nappe baisse durablement.', 7),
    ('b8da25ae-8e4e-5540-9763-782a4b45403e'::uuid, '63aaf518-1dc8-57bc-9c69-3b188f8f36d7'::uuid, 'Les fuites des réseaux de distribution peuvent dépasser 20 % de l’eau transportée.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Leur réparation est l’un des premiers gisements d’économie.', 8),
    ('c308abfa-e2bf-5c30-a55e-cea883f266b9'::uuid, '33679c9a-2652-537b-93f1-eeca7c993d04'::uuid, 'De quoi provient le pétrole ?', 'mcq', '["De la transformation de matière organique marine sur des millions d’années","De la fusion des roches du manteau","De la décomposition rapide de déchets végétaux","De réactions chimiques dans l’atmosphère"]'::jsonb, 0, 'Plancton et algues en sont à l’origine.', 1),
    ('5d09e855-0207-51bd-a2ad-93121090fbc8'::uuid, '33679c9a-2652-537b-93f1-eeca7c993d04'::uuid, 'Qu’est-ce qu’une roche mère ?', 'mcq', '["Une roche riche en matière organique où se forme le pétrole","Une roche imperméable qui piège le pétrole","Une roche poreuse où le pétrole s’accumule","Une roche volcanique"]'::jsonb, 0, 'La roche réservoir accueille ensuite les hydrocarbures.', 2),
    ('5de10db3-007a-5a95-b167-9ae8edb6a2db'::uuid, '33679c9a-2652-537b-93f1-eeca7c993d04'::uuid, 'Quel est le rôle de la roche couverture ?', 'mcq', '["Empêcher les hydrocarbures de s’échapper vers la surface","Produire la matière organique","Faciliter la migration","Chauffer le gisement"]'::jsonb, 0, 'Sans piège, pas de gisement exploitable.', 3),
    ('064f6322-cdea-5c4b-9cef-17a363dccada'::uuid, '33679c9a-2652-537b-93f1-eeca7c993d04'::uuid, 'Quelle méthode sert principalement à la prospection pétrolière ?', 'mcq', '["La sismique réflexion","La radiographie","L’analyse des marées","Le magnétisme terrestre uniquement"]'::jsonb, 0, 'Les échos d’ondes envoyées dans le sous-sol dessinent les structures.', 4),
    ('65771e13-5098-54ae-aef2-4fec4417d68a'::uuid, '33679c9a-2652-537b-93f1-eeca7c993d04'::uuid, 'Quel procédé sépare les composants du pétrole brut ?', 'mcq', '["La distillation fractionnée","La filtration sur sable","La décantation","L’électrolyse"]'::jsonb, 0, 'Elle exploite les différences de température d’ébullition.', 5),
    ('beac7160-3642-5d5e-bdcc-f929844a82bf'::uuid, '33679c9a-2652-537b-93f1-eeca7c993d04'::uuid, 'Pourquoi le pétrole est-il dit non renouvelable ?', 'mcq', '["Il met des millions d’années à se former et se consomme en quelques décennies","Il ne se forme plus du tout aujourd’hui","Il est interdit d’en extraire","Il n’en existe qu’un seul gisement"]'::jsonb, 0, 'L’échelle de temps de formation est sans rapport avec celle de la consommation.', 6),
    ('55bc129e-4464-5967-8f1b-2f3e820b795e'::uuid, '33679c9a-2652-537b-93f1-eeca7c993d04'::uuid, 'Quel gaz la combustion du pétrole libère-t-elle principalement ?', 'mcq', '["Le dioxyde de carbone","L’ozone","Le diazote","L’hélium"]'::jsonb, 0, 'C’est le principal gaz à effet de serre d’origine humaine.', 7),
    ('f7ac87e7-a527-5764-af8d-2f07914ef736'::uuid, '33679c9a-2652-537b-93f1-eeca7c993d04'::uuid, 'Le pétrole ne sert qu’à produire des carburants.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'La pétrochimie en tire plastiques, textiles, engrais et médicaments.', 8),
    ('d42c30ec-992a-5e1c-b8dc-e9c6819556d8'::uuid, 'b5eeedba-9e4e-58aa-91ca-016c0b483ee5'::uuid, 'Qu’est-ce qu’un écosystème ?', 'mcq', '["Un milieu et l’ensemble des êtres vivants qui l’occupent, avec leurs relations","Une population d’une seule espèce","Un climat régional","Une réserve naturelle protégée"]'::jsonb, 0, 'Il associe un biotope et une biocénose.', 1),
    ('ace0ef54-5743-53df-9907-2edd0c93c9b1'::uuid, 'b5eeedba-9e4e-58aa-91ca-016c0b483ee5'::uuid, 'Dans quel sens se déplacent les aires de répartition avec le réchauffement ?', 'mcq', '["Vers le nord et vers l’altitude dans l’hémisphère nord","Vers le sud et vers le niveau de la mer","Elles ne se déplacent pas","De façon aléatoire"]'::jsonb, 0, 'Les espèces de haute montagne n’ont plus où monter.', 2),
    ('f6c06546-ac93-5345-93ad-dfbc130cc050'::uuid, 'b5eeedba-9e4e-58aa-91ca-016c0b483ee5'::uuid, 'Qu’est-ce qu’une désynchronisation écologique ?', 'mcq', '["Un décalage entre deux espèces dépendantes, comme les oiseaux et leurs proies","Une extinction simultanée","Une migration groupée","Un changement de régime alimentaire"]'::jsonb, 0, 'Les nichées peuvent alors manquer de nourriture.', 3),
    ('46c80e7f-de7d-568b-a202-05dfd1a1e3bd'::uuid, 'b5eeedba-9e4e-58aa-91ca-016c0b483ee5'::uuid, 'Pourquoi les coraux blanchissent-ils ?', 'mcq', '["Ils expulsent les algues symbiotiques qui les nourrissent quand l’eau est trop chaude","Ils perdent leur squelette calcaire","Ils sont recouverts de sédiments","Ils manquent de lumière"]'::jsonb, 0, 'Si l’épisode dure, ils meurent.', 4),
    ('9b87bd82-01aa-55be-8097-22e63c77b105'::uuid, 'b5eeedba-9e4e-58aa-91ca-016c0b483ee5'::uuid, 'Quelles sont les trois réponses possibles d’une espèce au changement climatique ?', 'mcq', '["Se déplacer, s’adapter ou disparaître localement","Hiberner, migrer ou muter instantanément","Se reproduire plus, manger plus ou dormir plus","Changer d’espèce"]'::jsonb, 0, 'Une seule de ces issues est favorable.', 5),
    ('7b4072eb-2bb7-53db-8e3a-9b133685ec18'::uuid, 'b5eeedba-9e4e-58aa-91ca-016c0b483ee5'::uuid, 'Qu’est-ce qu’une rétroaction positive ?', 'mcq', '["Un effet qui amplifie sa propre cause","Un effet qui annule sa cause","Une conséquence bénéfique pour l’écosystème","Une adaptation réussie"]'::jsonb, 0, 'La fonte du permafrost libère du méthane, qui réchauffe davantage.', 6),
    ('fb8cd22b-d13d-5df9-b6c9-baee0a9f1386'::uuid, 'b5eeedba-9e4e-58aa-91ca-016c0b483ee5'::uuid, 'Qu’appelle-t-on services écosystémiques ?', 'mcq', '["Les bénéfices que les écosystèmes apportent aux sociétés humaines","Les mesures de protection des espèces","Les inventaires de biodiversité","Les subventions agricoles"]'::jsonb, 0, 'Pollinisation, épuration de l’eau, stockage de carbone.', 7),
    ('6607d7c8-ce10-53df-9caa-58814d74203f'::uuid, 'b5eeedba-9e4e-58aa-91ca-016c0b483ee5'::uuid, 'Les corridors écologiques permettent aux espèces de se déplacer entre milieux favorables.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Ils sont essentiels quand les aires de répartition se déplacent.', 8),
    ('aad8c247-9381-58cf-af63-acdb42d87c3d'::uuid, 'fbbe22a0-30c2-5434-9da2-8aa99b447113'::uuid, 'Que désigne le terme Anthropocène ?', 'mcq', '["Une époque géologique marquée par l’action humaine sur la planète","La période des grandes glaciations","L’ère des dinosaures","Le début de l’agriculture"]'::jsonb, 0, 'Le terme souligne l’ampleur de l’empreinte humaine.', 1),
    ('6fe613dc-18f2-5ba5-aa33-6f335d8044c0'::uuid, 'fbbe22a0-30c2-5434-9da2-8aa99b447113'::uuid, 'Quelles sont les grandes pressions sur la biodiversité ?', 'mcq', '["Climat, destruction des habitats, surexploitation, pollutions, espèces invasives","Uniquement le changement climatique","Uniquement la chasse","Uniquement la pollution plastique"]'::jsonb, 0, 'Leurs effets se cumulent.', 2),
    ('928d847f-0c9b-5ad9-b013-d036ed02a47e'::uuid, 'fbbe22a0-30c2-5434-9da2-8aa99b447113'::uuid, 'De combien le taux d’extinction actuel dépasse-t-il le taux naturel ?', 'mcq', '["De 100 à 1 000 fois","De 2 à 3 fois","De 10 000 fois","Il est identique"]'::jsonb, 0, 'On parle de sixième extinction de masse.', 3),
    ('c8f10401-f582-515e-bda9-16323d7911ac'::uuid, 'fbbe22a0-30c2-5434-9da2-8aa99b447113'::uuid, 'À quels niveaux la biodiversité se mesure-t-elle ?', 'mcq', '["Écosystèmes, espèces et gènes","Continents, pays et régions","Plantes, animaux et champignons","Terre, mer et air"]'::jsonb, 0, 'La diversité génétique conditionne la capacité future à s’adapter.', 4),
    ('c029dc09-560f-5780-9b31-b53fcde5d8c9'::uuid, 'fbbe22a0-30c2-5434-9da2-8aa99b447113'::uuid, 'Qu’est-ce que l’empreinte écologique ?', 'mcq', '["La surface nécessaire pour produire ce qu’on consomme et absorber ses déchets","La quantité de déchets produits par jour","Le nombre d’espèces disparues","La superficie des aires protégées"]'::jsonb, 0, 'Le jour du dépassement en est une traduction calendaire.', 5),
    ('c49ddd9f-049b-5939-a020-3baf2578ec6b'::uuid, 'fbbe22a0-30c2-5434-9da2-8aa99b447113'::uuid, 'Quels sont les trois piliers du développement durable ?', 'mcq', '["Économique, social et environnemental","Politique, militaire et culturel","Agricole, industriel et tertiaire","Local, national et mondial"]'::jsonb, 0, 'Il s’agit de répondre au présent sans compromettre l’avenir.', 6),
    ('58a188ff-320d-55eb-9f7b-be85fe42d5b5'::uuid, 'fbbe22a0-30c2-5434-9da2-8aa99b447113'::uuid, 'Que vise l’économie circulaire ?', 'mcq', '["Réduire, réutiliser, réparer et recycler","Produire davantage à coût constant","Délocaliser la production","Augmenter la consommation de matières premières"]'::jsonb, 0, 'Elle s’oppose au modèle extraire-produire-jeter.', 7),
    ('d1cf783f-14be-5de0-8c0d-5902e3417d48'::uuid, 'fbbe22a0-30c2-5434-9da2-8aa99b447113'::uuid, 'Le protocole de Montréal a permis à la couche d’ozone de se reconstituer.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est l’exemple type d’une décision collective aux effets mesurables.', 8),
    ('cd233d42-2aa6-534b-a57c-a3946e36e07d'::uuid, '8c1a0151-6db6-5055-bfbf-4ac92cc6e2c3'::uuid, 'Quels sont les besoins fondamentaux de toute cellule ?', 'mcq', '["Dioxygène, nutriments, eau, sels minéraux et vitamines","Dioxyde de carbone et azote","Uniquement du glucose","Uniquement du dioxygène"]'::jsonb, 0, 'Ils sont les mêmes quelle que soit la spécialité de la cellule.', 1),
    ('92c18b3d-ee1e-562e-ac6d-699f08cbc84d'::uuid, '8c1a0151-6db6-5055-bfbf-4ac92cc6e2c3'::uuid, 'Que produit la respiration cellulaire à partir du glucose et du dioxygène ?', 'mcq', '["Du dioxyde de carbone, de l’eau et de l’énergie","De l’oxygène et du glucose","Des protéines et des lipides","De l’azote et de l’eau"]'::jsonb, 0, 'L’énergie libérée fait fonctionner la cellule.', 2),
    ('dc6b9835-b2a8-55f5-8a11-9fb4640bd9af'::uuid, '8c1a0151-6db6-5055-bfbf-4ac92cc6e2c3'::uuid, 'Quelle est l’organisation du vivant, du plus simple au plus complexe ?', 'mcq', '["Cellule, tissu, organe, appareil, organisme","Organe, cellule, tissu, organisme","Tissu, cellule, appareil, organe","Organisme, appareil, cellule, tissu"]'::jsonb, 0, 'Chaque niveau intègre le précédent.', 3),
    ('bd4e5972-3186-5df1-98f4-8d531730865b'::uuid, '8c1a0151-6db6-5055-bfbf-4ac92cc6e2c3'::uuid, 'Quel appareil transporte nutriments et dioxygène jusqu’aux cellules ?', 'mcq', '["L’appareil circulatoire","L’appareil digestif","L’appareil respiratoire","L’appareil excréteur"]'::jsonb, 0, 'Il emporte aussi les déchets vers les organes d’élimination.', 4),
    ('20ae01aa-5128-572d-aa42-0ad138ac8dca'::uuid, '8c1a0151-6db6-5055-bfbf-4ac92cc6e2c3'::uuid, 'À quoi servent les acides aminés apportés par l’alimentation ?', 'mcq', '["À fabriquer les protéines","À stocker l’énergie sous forme de graisse","À transporter le dioxygène","À fabriquer l’ADN uniquement"]'::jsonb, 0, 'Les acides gras, eux, entrent dans les membranes et les réserves.', 5),
    ('d2649642-e729-5d47-868d-5d4a2753e1f3'::uuid, '8c1a0151-6db6-5055-bfbf-4ac92cc6e2c3'::uuid, 'Quelle part du glucose de l’organisme le cerveau consomme-t-il ?', 'mcq', '["Environ 20 %","Environ 2 %","Environ 50 %","Environ 5 %"]'::jsonb, 0, 'Alors qu’il ne représente que 2 % de la masse corporelle.', 6),
    ('28e9493e-9501-50f7-a4fc-71e70a101687'::uuid, '8c1a0151-6db6-5055-bfbf-4ac92cc6e2c3'::uuid, 'Quel est le point commun des alvéoles pulmonaires et des villosités intestinales ?', 'mcq', '["Ce sont des surfaces d’échange fines, étendues et très vascularisées","Elles produisent des hormones","Elles filtrent le sang","Elles stockent des nutriments"]'::jsonb, 0, 'Maximiser la surface dans un volume réduit est la solution générale.', 7),
    ('fa8deb36-b4b4-5f07-8dfe-bde0dcfc7112'::uuid, '8c1a0151-6db6-5055-bfbf-4ac92cc6e2c3'::uuid, 'Les besoins d’un muscle sont identiques au repos et pendant l’effort.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'La consommation de dioxygène et de glucose augmente fortement à l’effort.', 8),
    ('07c8f1b2-037c-5a44-b0fa-f7e1fe0bea63'::uuid, '64de307c-7f11-57fd-aad9-31e0c74fe7ff'::uuid, 'Où se font les échanges gazeux dans le poumon ?', 'mcq', '["Dans les alvéoles pulmonaires","Dans la trachée","Dans les bronches principales","Dans le larynx"]'::jsonb, 0, 'Elles offrent environ 100 m² de surface d’échange.', 1),
    ('9f13b2c1-20af-54cb-a41a-ddd7a099480e'::uuid, '64de307c-7f11-57fd-aad9-31e0c74fe7ff'::uuid, 'Quel muscle principal permet l’inspiration ?', 'mcq', '["Le diaphragme","Le cœur","Le muscle abdominal","Le muscle cardiaque droit"]'::jsonb, 0, 'Il s’abaisse et augmente le volume de la cage thoracique.', 2),
    ('90f64863-0797-55c0-a8dc-04456b58e66e'::uuid, '64de307c-7f11-57fd-aad9-31e0c74fe7ff'::uuid, 'Comment le dioxygène passe-t-il de l’alvéole au sang ?', 'mcq', '["Par diffusion, du plus concentré vers le moins concentré","Par transport actif avec dépense d’énergie","Par filtration mécanique","Grâce à une pompe cellulaire"]'::jsonb, 0, 'Le dioxyde de carbone fait le trajet inverse.', 3),
    ('a91fa656-fc35-5901-8e46-48fd61239650'::uuid, '64de307c-7f11-57fd-aad9-31e0c74fe7ff'::uuid, 'Quel rôle jouent les enzymes digestives ?', 'mcq', '["Elles coupent les grosses molécules en molécules simples","Elles broient mécaniquement les aliments","Elles transportent les nutriments dans le sang","Elles stockent le glucose"]'::jsonb, 0, 'C’est la digestion chimique, complémentaire de la digestion mécanique.', 4),
    ('e589d4af-cd4f-57bc-b0fd-013f73b45771'::uuid, '64de307c-7f11-57fd-aad9-31e0c74fe7ff'::uuid, 'Où se fait l’essentiel de l’absorption des nutriments ?', 'mcq', '["Dans l’intestin grêle","Dans l’estomac","Dans le gros intestin","Dans l’œsophage"]'::jsonb, 0, 'Ses villosités offrent environ 200 m² de surface.', 5),
    ('9a8d59ec-8210-5cb7-9a76-92d28415d1a0'::uuid, '64de307c-7f11-57fd-aad9-31e0c74fe7ff'::uuid, 'Quelle molécule fixe le dioxygène dans le sang ?', 'mcq', '["L’hémoglobine des globules rouges","Le plasma","Le glycogène","L’albumine"]'::jsonb, 0, 'Les nutriments, eux, circulent dissous dans le plasma.', 6),
    ('3137101b-57f2-56ff-92db-013502b20f94'::uuid, '64de307c-7f11-57fd-aad9-31e0c74fe7ff'::uuid, 'Quel organe le sang venu de l’intestin traverse-t-il en premier ?', 'mcq', '["Le foie","Le cœur","Le rein","Le poumon"]'::jsonb, 0, 'Il y trie les nutriments et stocke le glucose en glycogène.', 7),
    ('764b0d92-5161-53ca-a227-395508e2343c'::uuid, '64de307c-7f11-57fd-aad9-31e0c74fe7ff'::uuid, 'Le monoxyde de carbone prend la place du dioxygène sur l’hémoglobine.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est ce qui rend ce gaz mortel même à faible concentration.', 8),
    ('6647958f-6f45-55e2-b3ec-5f193e6d7e5b'::uuid, '27a82bd1-c124-500f-8854-4ae0b914105c'::uuid, 'Combien de cavités compte le cœur humain ?', 'mcq', '["Quatre","Deux","Trois","Six"]'::jsonb, 0, 'Deux oreillettes et deux ventricules, séparés par une cloison étanche.', 1),
    ('1ac52557-711d-5eec-81bf-99fdf13df77a'::uuid, '27a82bd1-c124-500f-8854-4ae0b914105c'::uuid, 'Que fait la circulation pulmonaire ?', 'mcq', '["Elle envoie le sang du ventricule droit vers les poumons","Elle envoie le sang vers tous les organes","Elle relie le foie à l’intestin","Elle filtre le sang dans les reins"]'::jsonb, 0, 'Le sang en revient enrichi en dioxygène.', 2),
    ('eb6b9443-5682-52e9-b750-f3d479d358c5'::uuid, '27a82bd1-c124-500f-8854-4ae0b914105c'::uuid, 'Où se font exclusivement les échanges entre le sang et les cellules ?', 'mcq', '["Dans les capillaires","Dans les artères","Dans les veines","Dans le cœur"]'::jsonb, 0, 'Leur paroi ne compte qu’une seule couche de cellules.', 3),
    ('7fb718e9-4643-5f7d-b556-8d93aeaf7520'::uuid, '27a82bd1-c124-500f-8854-4ae0b914105c'::uuid, 'Quel est le rôle des plaquettes sanguines ?', 'mcq', '["La coagulation","Le transport du dioxygène","La défense immunitaire","Le transport des nutriments"]'::jsonb, 0, 'Les globules blancs assurent la défense.', 4),
    ('0f305669-20c9-588b-b996-3baa64412b84'::uuid, '27a82bd1-c124-500f-8854-4ae0b914105c'::uuid, 'Quel déchet les reins éliminent-ils principalement ?', 'mcq', '["L’urée","Le dioxyde de carbone","Le glucose","L’hémoglobine"]'::jsonb, 0, 'C’est le déchet du métabolisme des protéines.', 5),
    ('e7fe3906-6f91-5c78-8f7d-1442887a8b96'::uuid, '27a82bd1-c124-500f-8854-4ae0b914105c'::uuid, 'La plupart des micro-organismes qui nous entourent sont-ils dangereux ?', 'mcq', '["Non, seule une minorité est pathogène","Oui, presque tous","Oui, tous les virus le sont","Aucun ne l’est"]'::jsonb, 0, 'Beaucoup sont même utiles, comme le microbiote.', 6),
    ('528238d3-264d-54ac-a5a7-63c3cb4b6179'::uuid, '27a82bd1-c124-500f-8854-4ae0b914105c'::uuid, 'Quelle différence entre contamination et infection ?', 'mcq', '["La contamination est l’entrée du micro-organisme, l’infection sa multiplication","La contamination touche la peau, l’infection le sang","La contamination est virale, l’infection bactérienne","Les deux mots sont synonymes"]'::jsonb, 0, 'Une contamination ne débouche pas toujours sur une infection.', 7),
    ('c169802e-8d9d-5a84-92c8-315235bd437c'::uuid, '27a82bd1-c124-500f-8854-4ae0b914105c'::uuid, 'La peau intacte et l’acidité de l’estomac constituent des barrières naturelles.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Elles empêchent l’installation de la plupart des pathogènes.', 8),
    ('0b168293-157a-5b98-980a-c9d263ab6f29'::uuid, 'cf0a22e1-88c8-5640-9a36-052e8dfd9ea5'::uuid, 'Que signifie « autotrophe » ?', 'mcq', '["Capable de fabriquer sa propre matière organique","Capable de se déplacer pour se nourrir","Qui se nourrit d’autres organismes","Qui vit sans dioxygène"]'::jsonb, 0, 'Les animaux, eux, sont hétérotrophes.', 1),
    ('35b541a5-edbb-5198-ac65-440d592259be'::uuid, 'cf0a22e1-88c8-5640-9a36-052e8dfd9ea5'::uuid, 'Quels sont les produits de la photosynthèse ?', 'mcq', '["Du glucose et du dioxygène","Du dioxyde de carbone et de l’eau","De l’azote et du glucose","Des sels minéraux et de l’eau"]'::jsonb, 0, 'Ils sont formés à partir de CO₂, d’eau et d’énergie lumineuse.', 2),
    ('3797a5ae-7b8d-55c9-9938-1fcd32a0ff21'::uuid, 'cf0a22e1-88c8-5640-9a36-052e8dfd9ea5'::uuid, 'Dans quel organite cellulaire se déroule la photosynthèse ?', 'mcq', '["Le chloroplaste","La mitochondrie","Le noyau","La vacuole"]'::jsonb, 0, 'Il contient la chlorophylle, qui capte la lumière.', 3),
    ('3f6aa2b2-d68f-5ff5-b4b6-99ecf9f2b5b2'::uuid, 'cf0a22e1-88c8-5640-9a36-052e8dfd9ea5'::uuid, 'Que prélèvent les racines dans le sol ?', 'mcq', '["De l’eau et des sels minéraux","Du dioxyde de carbone","Du glucose","Du dioxygène uniquement"]'::jsonb, 0, 'Les poils absorbants multiplient la surface de contact.', 4),
    ('670d56a9-22d6-5c9e-94a2-8de7ca8b365c'::uuid, 'cf0a22e1-88c8-5640-9a36-052e8dfd9ea5'::uuid, 'À quoi servent les stomates des feuilles ?', 'mcq', '["Aux échanges gazeux et au contrôle des pertes d’eau","À capter la lumière","À conduire la sève élaborée","À fixer la plante au sol"]'::jsonb, 0, 'Ils s’ouvrent et se ferment selon les conditions.', 5),
    ('06ffc625-89cd-59e6-8ed8-4308bae0e040'::uuid, 'cf0a22e1-88c8-5640-9a36-052e8dfd9ea5'::uuid, 'Que transporte la sève brute ?', 'mcq', '["De l’eau et des sels minéraux, des racines vers les feuilles","Des sucres, des feuilles vers les racines","Du dioxygène vers les racines","Des protéines vers les fruits"]'::jsonb, 0, 'La sève élaborée, riche en sucres, circule dans le phloème.', 6),
    ('0597343c-3147-5400-8471-28c0747dcd61'::uuid, 'cf0a22e1-88c8-5640-9a36-052e8dfd9ea5'::uuid, 'Qu’est-ce qu’une mycorhize ?', 'mcq', '["Une association entre les racines d’une plante et un champignon","Une maladie des feuilles","Un organe de réserve souterrain","Une graine résistante"]'::jsonb, 0, 'Le champignon améliore l’absorption, la plante fournit des sucres.', 7),
    ('97b09100-4f7d-592e-85a2-b083c283131f'::uuid, 'cf0a22e1-88c8-5640-9a36-052e8dfd9ea5'::uuid, 'Une plante ne respire que la nuit.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle respire jour et nuit ; le jour, la photosynthèse l’emporte.', 8),
    ('4ceeec30-0d8d-526d-9648-3ffb56892ab5'::uuid, 'da27f82d-df47-5658-886b-50486b1c77a3'::uuid, 'Qu’est-ce que la fécondation ?', 'mcq', '["La fusion d’un gamète mâle et d’un gamète femelle","La division de la cellule œuf","La production de gamètes","Le développement de l’embryon"]'::jsonb, 0, 'Elle donne une cellule œuf unique.', 1),
    ('e6abcc80-bc1e-507e-ab55-7032ca361ac1'::uuid, 'da27f82d-df47-5658-886b-50486b1c77a3'::uuid, 'Que contient la cellule œuf ?', 'mcq', '["La moitié de l’information génétique de chaque parent","La totalité de l’information de la mère","Une information génétique entièrement nouvelle","Deux fois l’information du père"]'::jsonb, 0, 'C’est ce qui explique la ressemblance partielle avec chaque parent.', 2),
    ('a73bd0ff-36f4-5d2d-a9d1-cf190d26b888'::uuid, 'da27f82d-df47-5658-886b-50486b1c77a3'::uuid, 'Pourquoi les espèces à fécondation externe produisent-elles énormément de gamètes ?', 'mcq', '["Parce que les chances de rencontre dans le milieu sont faibles","Parce que leurs gamètes sont plus petits","Parce qu’elles vivent moins longtemps","Parce qu’elles n’ont pas de partenaire"]'::jsonb, 0, 'La fécondation interne a un bien meilleur rendement.', 3),
    ('c5235ca4-5ebf-5029-9be0-ecb0c39437ee'::uuid, 'da27f82d-df47-5658-886b-50486b1c77a3'::uuid, 'Quel facteur détermine le sexe des petits chez certaines tortues ?', 'mcq', '["La température d’incubation","La taille de l’œuf","La profondeur du nid seule","Le nombre d’œufs pondus"]'::jsonb, 0, 'C’est un exemple frappant d’influence du milieu.', 4),
    ('90e10bf4-d30a-5c4c-955d-6383c23ca243'::uuid, 'da27f82d-df47-5658-886b-50486b1c77a3'::uuid, 'Qu’est-ce que la photopériode ?', 'mcq', '["La durée du jour, qui déclenche la reproduction saisonnière","L’intensité de la lumière solaire","La durée de gestation","Le temps d’incubation d’un œuf"]'::jsonb, 0, 'Elle synchronise la reproduction avec la bonne saison.', 5),
    ('7a205fca-b626-55e8-93bd-a098608439a3'::uuid, 'da27f82d-df47-5658-886b-50486b1c77a3'::uuid, 'De quoi dépend l’effectif d’une population ?', 'mcq', '["De la natalité, de la mortalité, de l’immigration et de l’émigration","De la seule natalité","De la seule mortalité","De la surface du territoire uniquement"]'::jsonb, 0, 'Ces quatre termes se compensent ou se cumulent.', 6),
    ('57fa4d20-0576-5f63-a512-040009796ac9'::uuid, 'da27f82d-df47-5658-886b-50486b1c77a3'::uuid, 'Quelle stratégie caractérise les grands mammifères ?', 'mcq', '["Peu de descendants, longuement pris en charge","Beaucoup de descendants peu protégés","Aucune prise en charge des jeunes","Une reproduction asexuée"]'::jsonb, 0, 'Les poissons et insectes suivent la stratégie inverse.', 7),
    ('ab10d54a-9951-5707-84f5-cfc34fb4459e'::uuid, 'da27f82d-df47-5658-886b-50486b1c77a3'::uuid, 'La fragmentation des milieux réduit le succès reproducteur d’une population.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Elle empêche les rencontres entre partenaires.', 8),
    ('5a9dfa6e-d7ef-598e-b197-9933ba43c51c'::uuid, '937f003f-1b29-5107-a6b3-f8fa9967577f'::uuid, 'Qu’est-ce que la reproduction asexuée ?', 'mcq', '["La production de descendants à partir d’un seul parent, sans fécondation","La fusion de deux gamètes identiques","La reproduction sans partenaire mais avec gamètes","La reproduction par pollinisation"]'::jsonb, 0, 'Les descendants sont des clones du parent.', 1),
    ('9899217a-704e-504b-8b20-463cb50d9085'::uuid, '937f003f-1b29-5107-a6b3-f8fa9967577f'::uuid, 'Quel mode de reproduction asexuée caractérise l’hydre et le corail ?', 'mcq', '["Le bourgeonnement","La scissiparité","La parthénogenèse","Le marcottage"]'::jsonb, 0, 'Un bourgeon se forme puis se détache du parent.', 2),
    ('ff24e0c8-f14d-5a5c-9af2-753705a3de9c'::uuid, '937f003f-1b29-5107-a6b3-f8fa9967577f'::uuid, 'Qu’est-ce que la parthénogenèse ?', 'mcq', '["Le développement d’un ovule sans fécondation","La division d’un individu en deux","La régénération d’un fragment","La fusion de deux ovules"]'::jsonb, 0, 'Les pucerons la pratiquent en été.', 3),
    ('317a3bbc-400f-5ad8-9c5f-4bc1be28cc72'::uuid, '937f003f-1b29-5107-a6b3-f8fa9967577f'::uuid, 'Comment le fraisier se multiplie-t-il de façon asexuée ?', 'mcq', '["Par stolons","Par bulbes","Par rhizomes","Par tubercules"]'::jsonb, 0, 'La pomme de terre utilise des tubercules, la tulipe des bulbes.', 4),
    ('8473cc46-3803-5bb2-b21b-0ad0fa5bc56a'::uuid, '937f003f-1b29-5107-a6b3-f8fa9967577f'::uuid, 'Quel est le principal avantage de la reproduction asexuée ?', 'mcq', '["La rapidité de colonisation, sans besoin de partenaire","La diversité génétique produite","La résistance aux maladies","La longévité des individus"]'::jsonb, 0, 'Un individu isolé suffit à occuper un milieu favorable.', 5),
    ('5b72f811-4ae5-5568-9bb3-1dec34e76369'::uuid, '937f003f-1b29-5107-a6b3-f8fa9967577f'::uuid, 'Quel est son principal inconvénient ?', 'mcq', '["L’absence de diversité génétique dans la population","La lenteur du processus","Le coût énergétique élevé","La nécessité de deux parents"]'::jsonb, 0, 'Une maladie peut anéantir toute la population.', 6),
    ('85cfd4e5-c559-5ccd-a79f-bebea776b4f6'::uuid, '937f003f-1b29-5107-a6b3-f8fa9967577f'::uuid, 'Que fait le puceron selon la saison ?', 'mcq', '["Il se reproduit par parthénogenèse en été et sexuellement à l’automne","Il ne se reproduit qu’au printemps","Il ne pratique que la reproduction sexuée","Il alterne bourgeonnement et scissiparité"]'::jsonb, 0, 'Les œufs issus de la reproduction sexuée résistent à l’hiver.', 7),
    ('3ae0555b-fcf7-5f42-9b22-9f657a8dddb0'::uuid, '937f003f-1b29-5107-a6b3-f8fa9967577f'::uuid, 'Les descendants d’une reproduction asexuée sont génétiquement identiques au parent.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Ce sont des clones, aux mutations près.', 8),
    ('cc02404e-f81d-5eff-a449-3153954d8ce3'::uuid, '32e83713-94ff-540a-8544-20c3178aa0b6'::uuid, 'Combien de chromosomes contient une cellule humaine ?', 'mcq', '["46, soit 23 paires","23, soit 46 paires","48, soit 24 paires","44, soit 22 paires"]'::jsonb, 0, 'Un chromosome de chaque paire vient de chaque parent.', 1),
    ('567c5a6e-4b23-57bd-8d83-626d83b90a4d'::uuid, '32e83713-94ff-540a-8544-20c3178aa0b6'::uuid, 'Quelle paire de chromosomes détermine le sexe ?', 'mcq', '["La 23e paire","La première paire","La 21e paire","La 46e paire"]'::jsonb, 0, 'XX chez la femme, XY chez l’homme.', 2),
    ('10b467cf-50bd-59c4-9d52-1e129f2615d0'::uuid, '32e83713-94ff-540a-8544-20c3178aa0b6'::uuid, 'Que produit la mitose ?', 'mcq', '["Deux cellules filles identiques à 46 chromosomes","Quatre gamètes à 23 chromosomes","Une cellule œuf","Deux cellules à 23 chromosomes"]'::jsonb, 0, 'Elle assure croissance, renouvellement et réparation.', 3),
    ('8c7c2de5-4ab3-5ca1-9c14-e11a5187004b'::uuid, '32e83713-94ff-540a-8544-20c3178aa0b6'::uuid, 'Que fait la méiose ?', 'mcq', '["Elle réduit le nombre de chromosomes de 46 à 23 dans les gamètes","Elle double le nombre de chromosomes","Elle produit deux cellules identiques","Elle répare l’ADN endommagé"]'::jsonb, 0, 'Chaque gamète reçoit un chromosome de chaque paire.', 4),
    ('618d36da-2d30-5b08-8069-344fad55c366'::uuid, '32e83713-94ff-540a-8544-20c3178aa0b6'::uuid, 'Pourquoi la réduction du nombre de chromosomes est-elle indispensable ?', 'mcq', '["Sinon le nombre doublerait à chaque génération","Sinon les gamètes seraient trop gros","Sinon la fécondation serait impossible","Sinon les chromosomes se casseraient"]'::jsonb, 0, 'La méiose divise, la fécondation rétablit.', 5),
    ('a89a4775-5282-56a6-a57c-8c8f68c2fbc8'::uuid, '32e83713-94ff-540a-8544-20c3178aa0b6'::uuid, 'Pourquoi deux enfants des mêmes parents ne sont-ils pas identiques ?', 'mcq', '["La répartition des chromosomes et la fécondation se font au hasard","Ils reçoivent des chromosomes de parents différents","Leur ADN change après la naissance","La méiose supprime des chromosomes au hasard"]'::jsonb, 0, 'Les vrais jumeaux font exception : ils viennent d’une même cellule œuf.', 6),
    ('961572f5-b3ae-5e99-9aab-04eb810c87e3'::uuid, '32e83713-94ff-540a-8544-20c3178aa0b6'::uuid, 'À quoi correspond la trisomie 21 ?', 'mcq', '["À trois exemplaires du chromosome 21","À l’absence du chromosome 21","À une anomalie de la 23e paire","À un chromosome cassé"]'::jsonb, 0, 'Le caryotype permet de la mettre en évidence.', 7),
    ('6a51bdba-931a-51be-9428-d65ed8665276'::uuid, '32e83713-94ff-540a-8544-20c3178aa0b6'::uuid, 'Une musculature développée par l’entraînement se transmet aux enfants.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Un caractère acquis ne modifie pas l’information génétique des gamètes.', 8),
    ('c133911b-7523-5248-9ca7-4ce1e977fb78'::uuid, '3c48ae86-05f1-5b9b-bdd6-e077490a866d'::uuid, 'Sur quoi repose la classification actuelle des êtres vivants ?', 'mcq', '["Sur les liens de parenté et les caractères partagés","Sur la taille et le poids des organismes","Sur le milieu de vie","Sur l’ordre alphabétique des noms"]'::jsonb, 0, 'Plus les caractères dérivés partagés sont nombreux, plus l’ancêtre commun est récent.', 1),
    ('f504e4c4-000c-5fd8-a681-f49267550280'::uuid, '3c48ae86-05f1-5b9b-bdd6-e077490a866d'::uuid, 'Qu’est-ce qu’une homologie ?', 'mcq', '["Une ressemblance de plan d’organisation héritée d’un ancêtre commun","Une ressemblance due à un mode de vie identique","Une différence entre deux espèces proches","Une mutation partagée par hasard"]'::jsonb, 0, 'Le membre antérieur des vertébrés en est l’exemple classique.', 2),
    ('c38c1388-9120-5ac6-8dee-3a7afc3297fc'::uuid, '3c48ae86-05f1-5b9b-bdd6-e077490a866d'::uuid, 'Qu’est-ce qu’une convergence évolutive ?', 'mcq', '["Une ressemblance due à un mode de vie commun, sans lien de parenté proche","Un héritage direct d’un ancêtre commun","Une extinction simultanée de deux groupes","Un croisement entre deux espèces"]'::jsonb, 0, 'L’aile d’oiseau et l’aile d’insecte n’ont pas la même origine.', 3),
    ('12c3b41f-fc1b-5c10-a629-591bf9442790'::uuid, '3c48ae86-05f1-5b9b-bdd6-e077490a866d'::uuid, 'Quel argument moléculaire montre la parenté de tous les êtres vivants ?', 'mcq', '["Ils utilisent tous l’ADN et le même code génétique","Ils ont tous des chromosomes en même nombre","Ils respirent tous du dioxygène","Ils ont tous des cellules à noyau"]'::jsonb, 0, 'La proximité des séquences mesure la proximité de parenté.', 4),
    ('bf058177-c273-5278-8f8d-ed0d267cdf53'::uuid, '3c48ae86-05f1-5b9b-bdd6-e077490a866d'::uuid, 'Que représente un nœud dans un arbre phylogénétique ?', 'mcq', '["Un ancêtre commun hypothétique","Une espèce actuelle","Une extinction de masse","Un fossile daté"]'::jsonb, 0, 'Les branches représentent les lignées issues de cet ancêtre.', 5),
    ('88c5ccac-7775-5638-b9e7-b9fdf170905a'::uuid, '3c48ae86-05f1-5b9b-bdd6-e077490a866d'::uuid, 'Quand la vie apparaît-elle sur Terre ?', 'mcq', '["Il y a environ 3,8 milliards d’années","Il y a environ 540 millions d’années","Il y a environ 66 millions d’années","Il y a environ 300 000 ans"]'::jsonb, 0, 'Sous forme unicellulaire, bien avant la pluricellularité.', 6),
    ('f9e0f3b0-332a-57c2-889a-4bfa8c7e5a7b'::uuid, '3c48ae86-05f1-5b9b-bdd6-e077490a866d'::uuid, 'Quand disparaissent les dinosaures non aviens ?', 'mcq', '["Il y a environ 66 millions d’années","Il y a environ 540 millions d’années","Il y a environ 2 millions d’années","Il y a environ 250 millions d’années"]'::jsonb, 0, 'Leur disparition ouvre la voie à la diversification des mammifères.', 7),
    ('8fc9c709-d6b6-5713-bab4-0e61d3d71432'::uuid, '3c48ae86-05f1-5b9b-bdd6-e077490a866d'::uuid, 'Les groupes du vivant sont emboîtés : les humains sont des primates, des mammifères et des vertébrés.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'L’emboîtement traduit la succession des ancêtres communs.', 8),
    ('90fa8f72-4d14-50c1-a4b3-e4c98ca65ef7'::uuid, 'f74f2c9b-703f-5def-ac8b-5f44c5d79f94'::uuid, 'Qui décrit le mécanisme de la sélection naturelle en 1859 ?', 'mcq', '["Charles Darwin","Jean-Baptiste de Lamarck","Gregor Mendel","Louis Pasteur"]'::jsonb, 0, 'Dans L’Origine des espèces.', 1),
    ('ab307b6d-6523-5253-b054-f4ac9646ca62'::uuid, 'f74f2c9b-703f-5def-ac8b-5f44c5d79f94'::uuid, 'D’où viennent les variations héréditaires dans une population ?', 'mcq', '["Des mutations aléatoires de l’ADN et du brassage de la reproduction sexuée","De la volonté des individus de s’adapter","De l’usage ou du non-usage des organes","Du climat qui modifie directement les gènes"]'::jsonb, 0, 'Le hasard fournit, le milieu trie.', 2),
    ('2ed2bdfd-2dc5-51e5-9399-3940d06a9fa5'::uuid, 'f74f2c9b-703f-5def-ac8b-5f44c5d79f94'::uuid, 'Que fait la sélection naturelle ?', 'mcq', '["Elle trie les variations existantes selon leur avantage dans le milieu","Elle crée de nouvelles mutations utiles","Elle supprime toutes les mutations","Elle oriente les mutations vers un but"]'::jsonb, 0, 'Elle ne crée rien : elle sélectionne.', 3),
    ('f6686c0a-1a28-5997-92a7-8776d9b3551c'::uuid, 'f74f2c9b-703f-5def-ac8b-5f44c5d79f94'::uuid, 'Que montre l’exemple de la phalène du bouleau ?', 'mcq', '["La forme sombre a été favorisée quand les troncs étaient noircis par la suie","Les papillons changent de couleur au cours de leur vie","La pollution provoque directement des mutations utiles","La forme claire a toujours dominé"]'::jsonb, 0, 'Quand l’air est redevenu propre, la forme claire est redevenue majoritaire.', 4),
    ('b52b90d0-e74b-5388-8383-1af8060c2ef3'::uuid, 'f74f2c9b-703f-5def-ac8b-5f44c5d79f94'::uuid, 'Pourquoi des bactéries deviennent-elles résistantes à un antibiotique ?', 'mcq', '["Les bactéries porteuses d’une mutation de résistance survivent et se multiplient","Elles apprennent à résister au contact du médicament","L’antibiotique crée la mutation de résistance","Elles échangent leur ADN avec l’hôte"]'::jsonb, 0, 'C’est la sélection naturelle observable en quelques jours.', 5),
    ('9e19485f-2176-5633-8f2b-64f6a8079f84'::uuid, 'f74f2c9b-703f-5def-ac8b-5f44c5d79f94'::uuid, 'Qu’est-ce que la dérive génétique ?', 'mcq', '["Une modification des fréquences par simple hasard, surtout en petite population","Une sélection par le milieu","Un échange de gènes entre espèces","Une mutation dirigée"]'::jsonb, 0, 'Elle agit indépendamment de tout avantage.', 6),
    ('f56ed1f7-01b2-531e-ba32-afef64321354'::uuid, 'f74f2c9b-703f-5def-ac8b-5f44c5d79f94'::uuid, 'Qu’est-ce que la spéciation ?', 'mcq', '["L’apparition d’une espèce nouvelle après isolement durable de populations","La disparition d’une espèce","Le croisement de deux espèces","La classification des espèces"]'::jsonb, 0, 'Les populations isolées accumulent des différences jusqu’à ne plus pouvoir se reproduire entre elles.', 7),
    ('07fdba01-08b4-5a4b-9a2a-1804641febd3'::uuid, 'f74f2c9b-703f-5def-ac8b-5f44c5d79f94'::uuid, 'L’évolution a un but et tend vers des organismes toujours plus perfectionnés.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle n’a aucun but : seul compte l’avantage reproductif dans un milieu donné.', 8),
    ('8de76c22-c166-5977-aed1-1a4013bb7f71'::uuid, '663525b9-7d8b-5344-b54d-16a9487227e9'::uuid, 'Où se trouve l’information génétique dans une cellule ?', 'mcq', '["Dans le noyau","Dans la membrane","Dans le cytoplasme uniquement","Dans les mitochondries uniquement"]'::jsonb, 0, 'Les expériences de transfert de noyau l’ont démontré.', 1),
    ('69fc816e-25c7-54d8-923c-591785940763'::uuid, '663525b9-7d8b-5344-b54d-16a9487227e9'::uuid, 'Qu’a démontré le clonage de la brebis Dolly en 1996 ?', 'mcq', '["Le noyau transféré impose les caractères de l’individu donneur","L’environnement détermine seul les caractères","Les gamètes sont indispensables au clonage","L’ADN est présent dans le cytoplasme"]'::jsonb, 0, 'Il repose sur le transfert de noyau dans un ovule énucléé.', 2),
    ('a26015a0-e348-552f-9c9d-24d37a64d9f0'::uuid, '663525b9-7d8b-5344-b54d-16a9487227e9'::uuid, 'Qu’est-ce qu’un gène ?', 'mcq', '["Un segment d’ADN portant l’information d’un caractère","Un chromosome entier","Une protéine du noyau","Une cellule spécialisée"]'::jsonb, 0, 'Il porte l’information pour fabriquer une protéine.', 3),
    ('91e79dd8-e8f6-50ee-a911-1ea87bca8717'::uuid, '663525b9-7d8b-5344-b54d-16a9487227e9'::uuid, 'Quelle est la structure de l’ADN ?', 'mcq', '["Une double hélice formée de deux brins complémentaires","Une simple chaîne linéaire","Un anneau fermé","Un réseau ramifié"]'::jsonb, 0, 'Elle a été décrite en 1953.', 4),
    ('bca61841-395d-53b1-a044-fd16997c6836'::uuid, '663525b9-7d8b-5344-b54d-16a9487227e9'::uuid, 'Quelles bases s’apparient dans l’ADN ?', 'mcq', '["A avec T, et G avec C","A avec G, et T avec C","A avec C, et T avec G","Chaque base avec elle-même"]'::jsonb, 0, 'Cette complémentarité permet la copie fidèle de l’ADN.', 5),
    ('2b7e8648-8e31-5038-86e3-148bc87afb82'::uuid, '663525b9-7d8b-5344-b54d-16a9487227e9'::uuid, 'L’ADN est-il le même dans toutes les cellules d’un individu ?', 'mcq', '["Oui, ce sont les gènes exprimés qui changent selon les tissus","Non, chaque organe a son propre ADN","Non, seules les cellules reproductrices en contiennent","Oui, et tous les gènes s’y expriment de la même façon"]'::jsonb, 0, 'La spécialisation vient de l’expression, pas du contenu.', 6),
    ('bcc606e6-e66b-5da9-95ab-66c55db89197'::uuid, '663525b9-7d8b-5344-b54d-16a9487227e9'::uuid, 'Qu’est-ce qui explique la diversité des individus d’une même espèce ?', 'mcq', '["Une combinaison unique de versions de gènes, et l’influence de l’environnement","L’environnement seul","Les gènes seuls","Le hasard des mutations après la naissance"]'::jsonb, 0, 'La taille adulte dépend des gènes et de la nutrition.', 7),
    ('2aa79fa3-f644-561c-b89e-15320b838082'::uuid, '663525b9-7d8b-5344-b54d-16a9487227e9'::uuid, 'Les vrais jumeaux sont strictement identiques en tout point.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Ils partagent le même ADN, mais l’environnement les distingue.', 8),
    ('241c14d2-cbec-5d15-96a2-344338cacb11'::uuid, 'a71392c4-9093-5084-a8cf-75a354a0b71a'::uuid, 'Qu’est-ce qu’un allèle ?', 'mcq', '["Une version d’un gène","Un chromosome entier","Une cellule reproductrice","Une protéine codée par un gène"]'::jsonb, 0, 'Un gène occupe toujours le même locus, mais peut avoir plusieurs versions.', 1),
    ('0a036a2f-b5d1-58d0-9a46-5a9981209cbf'::uuid, 'a71392c4-9093-5084-a8cf-75a354a0b71a'::uuid, 'Combien d’allèles de chaque gène un individu porte-t-il ?', 'mcq', '["Deux, un de chaque parent","Un seul","Quatre","Autant que de chromosomes"]'::jsonb, 0, 'Les chromosomes vont par paires.', 2),
    ('84545c89-d2de-5846-8419-3879de66a7b1'::uuid, 'a71392c4-9093-5084-a8cf-75a354a0b71a'::uuid, 'Que signifie être hétérozygote pour un gène ?', 'mcq', '["Porter deux allèles différents de ce gène","Porter deux allèles identiques","Ne porter qu’un seul allèle","Porter un allèle muté"]'::jsonb, 0, 'Homozygote signifie deux allèles identiques.', 3),
    ('aabe6405-552c-50a4-8579-26150f3996d2'::uuid, 'a71392c4-9093-5084-a8cf-75a354a0b71a'::uuid, 'Quand un allèle récessif s’exprime-t-il ?', 'mcq', '["Seulement s’il est présent en double exemplaire","Dès qu’il est présent une fois","Jamais","Uniquement chez les femmes"]'::jsonb, 0, 'Un allèle dominant s’exprime dès qu’il est présent.', 4),
    ('b8737e4d-98dd-5fb7-b53a-89d0ecd262ed'::uuid, 'a71392c4-9093-5084-a8cf-75a354a0b71a'::uuid, 'Quelle différence entre génotype et phénotype ?', 'mcq', '["Le génotype est l’ensemble des allèles, le phénotype les caractères observables","Le génotype est visible, le phénotype non","Le génotype concerne les gamètes, le phénotype les cellules du corps","Ils sont synonymes"]'::jsonb, 0, 'Deux génotypes différents peuvent donner le même phénotype.', 5),
    ('c3c9e28f-f829-544a-9241-73a8dbda1e46'::uuid, 'a71392c4-9093-5084-a8cf-75a354a0b71a'::uuid, 'Comment un enfant peut-il être atteint d’une maladie récessive sans parent malade ?', 'mcq', '["Chacun des parents était porteur sain d’un allèle récessif","La maladie est apparue par mutation après la naissance","Un seul parent a transmis les deux allèles","La maladie vient de l’environnement seul"]'::jsonb, 0, 'Les parents hétérozygotes ne présentent pas la maladie.', 6),
    ('0dfff377-7b14-5774-abf5-4be6ee211925'::uuid, 'a71392c4-9093-5084-a8cf-75a354a0b71a'::uuid, 'D’où viennent les nouveaux allèles ?', 'mcq', '["De mutations de la séquence d’ADN","Du brassage lors de la fécondation","De l’alimentation","De l’entraînement physique"]'::jsonb, 0, 'Ultraviolets, tabac et rayonnements sont des agents mutagènes.', 7),
    ('d0456e3c-2937-50a4-8d5e-538cb145c2f9'::uuid, 'a71392c4-9093-5084-a8cf-75a354a0b71a'::uuid, 'Une population génétiquement uniforme est plus vulnérable à une maladie nouvelle.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Aucun individu ne dispose d’une résistance différente.', 8),
    ('95240dc4-3b45-5fec-b1ee-bcef681f4f64'::uuid, 'e830d08c-ab17-5cca-9118-a0f83d13debc'::uuid, 'Que se passe-t-il lors de la réplication de l’ADN ?', 'mcq', '["Chaque brin sert de modèle pour fabriquer un brin complémentaire","Les deux brins sont détruits puis reconstruits","L’ADN se transforme en protéine","Les chromosomes s’échangent entre paires"]'::jsonb, 0, 'On obtient deux molécules identiques à l’originale.', 1),
    ('05e6336c-9527-5e91-b1f3-9fbd35b7048a'::uuid, 'e830d08c-ab17-5cca-9118-a0f83d13debc'::uuid, 'Quel est le résultat d’une mitose ?', 'mcq', '["Deux cellules filles identiques à la cellule mère","Quatre cellules à 23 chromosomes","Une cellule œuf","Deux gamètes"]'::jsonb, 0, 'Elle assure la stabilité génétique de l’organisme.', 2),
    ('1ccf07d6-0d81-53b7-a61b-622c5dc55184'::uuid, 'e830d08c-ab17-5cca-9118-a0f83d13debc'::uuid, 'Qu’apportent la méiose et la fécondation ?', 'mcq', '["La variabilité génétique des descendants","La stabilité de l’information génétique","La réparation des mutations","La copie fidèle des chromosomes"]'::jsonb, 0, 'Chaque individu issu de reproduction sexuée est unique.', 3),
    ('a0ddbb66-2c58-5ffa-b943-04258da954bc'::uuid, 'e830d08c-ab17-5cca-9118-a0f83d13debc'::uuid, 'Que suggère un caractère qui saute une génération dans un arbre généalogique ?', 'mcq', '["Qu’il est probablement récessif","Qu’il est dominant","Qu’il est acquis","Qu’il est porté par le chromosome Y"]'::jsonb, 0, 'Les porteurs sains le transmettent sans le présenter.', 4),
    ('ba8aebdc-3ed2-54ca-a492-853641d2a538'::uuid, 'e830d08c-ab17-5cca-9118-a0f83d13debc'::uuid, 'Quel indice suggère un caractère porté par le chromosome X ?', 'mcq', '["Il touche presque uniquement les garçons","Il touche uniquement les filles","Il saute deux générations","Il apparaît après 40 ans"]'::jsonb, 0, 'Daltonisme et hémophilie en sont les exemples classiques.', 5),
    ('d8db2952-f01a-5af3-9fbc-92398b02f835'::uuid, 'e830d08c-ab17-5cca-9118-a0f83d13debc'::uuid, 'Quelle mutation est transmissible à la descendance ?', 'mcq', '["Celle qui survient dans une cellule reproductrice","Celle qui survient dans une cellule de la peau","Toutes les mutations","Aucune mutation"]'::jsonb, 0, 'Une mutation dans une cellule du corps ne touche que la descendance de cette cellule.', 6),
    ('9ae9911c-9ae2-58c2-bef3-9e8d2855c492'::uuid, 'e830d08c-ab17-5cca-9118-a0f83d13debc'::uuid, 'Comment naissent certains cancers ?', 'mcq', '["À partir de mutations non réparées dans des cellules du corps","Par transmission systématique des parents","Par contamination virale exclusivement","Par carence en vitamines"]'::jsonb, 0, 'La cellule mutée se multiplie sans contrôle.', 7),
    ('d73608dd-d488-59d9-ae7d-7a4872da1a84'::uuid, 'e830d08c-ab17-5cca-9118-a0f83d13debc'::uuid, 'La mitose conserve l’information, la méiose et la fécondation la brassent.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Un organisme a besoin des deux : stabilité et variabilité.', 8),
    ('fb43d2e0-c6aa-5523-b3b8-57945cf47e68'::uuid, 'e7694393-ac98-54e6-b9b7-5efd0bfe0f03'::uuid, 'Que consomment davantage les muscles pendant un effort ?', 'mcq', '["Du glucose et du dioxygène","Du dioxyde de carbone et de l’eau","Des protéines uniquement","De l’azote"]'::jsonb, 0, 'Ils produisent en retour du CO₂ et de la chaleur.', 1),
    ('25069a0c-06c9-5493-b92c-5bee68ed97bb'::uuid, 'e7694393-ac98-54e6-b9b7-5efd0bfe0f03'::uuid, 'Comment le sang est-il redistribué à l’effort ?', 'mcq', '["Vers les muscles, au détriment des organes digestifs","Vers les organes digestifs","De façon inchangée","Uniquement vers le cerveau"]'::jsonb, 0, 'Les vaisseaux musculaires se dilatent, les vaisseaux digestifs se contractent.', 2),
    ('430013fc-0bd3-5986-9b8a-8facd5828c25'::uuid, 'e7694393-ac98-54e6-b9b7-5efd0bfe0f03'::uuid, 'De combien la consommation de dioxygène peut-elle être multipliée à l’effort ?', 'mcq', '["Par 10 ou plus","Par 2","Elle reste identique","Elle diminue"]'::jsonb, 0, 'La ventilation augmente en fréquence et en amplitude.', 3),
    ('a715d414-7a71-541d-9cba-36a884359784'::uuid, 'e7694393-ac98-54e6-b9b7-5efd0bfe0f03'::uuid, 'Dans quoi le muscle puise-t-il en premier ?', 'mcq', '["Ses réserves de glycogène","Les lipides du tissu adipeux","Les protéines musculaires","Le calcium des os"]'::jsonb, 0, 'Le glucose sanguin puis les lipides prennent ensuite le relais.', 4),
    ('4f37eb2c-565b-5129-a22a-6fca9e2aaafc'::uuid, 'e7694393-ac98-54e6-b9b7-5efd0bfe0f03'::uuid, 'Que se passe-t-il quand l’apport en dioxygène devient insuffisant ?', 'mcq', '["La fermentation lactique prend le relais","La respiration cellulaire s’accélère","Le muscle stocke du glycogène","Le cœur ralentit"]'::jsonb, 0, 'Elle est moins efficace et produit de l’acide lactique.', 5),
    ('cbb4e4ec-86df-5fe5-8a24-fb84a04515a4'::uuid, 'e7694393-ac98-54e6-b9b7-5efd0bfe0f03'::uuid, 'À quoi sert la sudation pendant l’effort ?', 'mcq', '["À évacuer la chaleur produite","À éliminer le dioxyde de carbone","À apporter du glucose à la peau","À augmenter le débit cardiaque"]'::jsonb, 0, 'Elle coûte de l’eau et des sels, d’où le risque de déshydratation.', 6),
    ('f71f7ff2-b4fc-56b3-af8b-6eb7d90fdec5'::uuid, 'e7694393-ac98-54e6-b9b7-5efd0bfe0f03'::uuid, 'Quel effet l’entraînement régulier a-t-il sur la fréquence cardiaque de repos ?', 'mcq', '["Elle diminue","Elle augmente","Elle reste identique","Elle devient irrégulière"]'::jsonb, 0, 'Le cœur, plus puissant, éjecte davantage à chaque battement.', 7),
    ('75eb0b00-b17f-5b9d-8e77-6200a55420da'::uuid, 'e7694393-ac98-54e6-b9b7-5efd0bfe0f03'::uuid, 'Une douleur pendant l’effort est un signal d’alerte à ne pas ignorer.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Crampes, essoufflement et douleur signalent une limite atteinte.', 8),
    ('e9dd42e9-500e-5a09-a934-8db7e7781fd6'::uuid, 'e5fe4192-9bbc-587a-8add-e63d04413200'::uuid, 'Comment l’OMS définit-elle la santé ?', 'mcq', '["Un état de complet bien-être physique, mental et social","L’absence de maladie","Une bonne condition physique","Une espérance de vie élevée"]'::jsonb, 0, 'L’activité physique agit sur les trois dimensions.', 1),
    ('28a638cf-a115-59d1-8985-d9fa3b44e3f6'::uuid, 'e5fe4192-9bbc-587a-8add-e63d04413200'::uuid, 'Quelle durée d’activité physique quotidienne l’OMS recommande-t-elle aux adolescents ?', 'mcq', '["Au moins 60 minutes","Au moins 20 minutes","Au moins 2 heures","Au moins 10 minutes"]'::jsonb, 0, 'D’intensité modérée à soutenue.', 2),
    ('6e4e56d2-5756-5fbd-bd77-a70f12925892'::uuid, 'e5fe4192-9bbc-587a-8add-e63d04413200'::uuid, 'Quel bénéfice osseux l’activité physique apporte-t-elle ?', 'mcq', '["Une densité osseuse plus élevée, qui prévient l’ostéoporose","Un allongement des os","Une diminution du nombre d’articulations","Un durcissement des cartilages"]'::jsonb, 0, 'L’os se renforce sous contrainte mécanique.', 3),
    ('d468ce78-f737-54e8-aef6-a9c2b45b4bda'::uuid, 'e5fe4192-9bbc-587a-8add-e63d04413200'::uuid, 'La sédentarité est-elle un facteur de risque à elle seule ?', 'mcq', '["Oui, indépendamment des autres facteurs","Non, seulement combinée au tabac","Non, si l’alimentation est équilibrée","Uniquement après 50 ans"]'::jsonb, 0, 'Rester assis longtemps augmente plusieurs risques.', 4),
    ('cdc7378f-37da-572c-8458-00d25725b805'::uuid, 'e5fe4192-9bbc-587a-8add-e63d04413200'::uuid, 'Quels signes indiquent une surcharge d’entraînement ?', 'mcq', '["Fatigue persistante, blessures répétées, troubles du sommeil","Une progression rapide des performances","Une meilleure récupération","Un appétit accru"]'::jsonb, 0, 'S’entraîner trop nuit autant que pas assez.', 5),
    ('2810b4e9-a26d-563b-ba05-85601ad4ac16'::uuid, 'e5fe4192-9bbc-587a-8add-e63d04413200'::uuid, 'Quel nutriment est privilégié pour les efforts d’endurance ?', 'mcq', '["Les glucides complexes","Les protéines","Les lipides saturés","Les vitamines liposolubles"]'::jsonb, 0, 'Les protéines servent surtout à la réparation musculaire.', 6),
    ('ac21dc20-916e-576f-94ce-cf37fe2536e6'::uuid, 'e5fe4192-9bbc-587a-8add-e63d04413200'::uuid, 'Quels risques le dopage fait-il courir ?', 'mcq', '["Des troubles cardiaques, hormonaux et psychiques","Une simple sanction sportive","Aucun risque à faible dose","Une perte de masse musculaire uniquement"]'::jsonb, 0, 'La règle sportive rejoint ici la règle sanitaire.', 7),
    ('4cbc1670-5ddd-5f5e-a1e7-a2a5e61ce295'::uuid, 'e5fe4192-9bbc-587a-8add-e63d04413200'::uuid, 'La pratique d’une activité physique ne dépend que de la volonté individuelle.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Équipements, pistes cyclables et sécurité des trajets pèsent aussi.', 8),
    ('5c978288-1ea3-55fa-bc50-cd7726c781ac'::uuid, '2bf5052b-68e6-5ee0-a2aa-9f0891c7666a'::uuid, 'De quoi se compose le système nerveux central ?', 'mcq', '["De l’encéphale et de la moelle épinière","Des nerfs sensitifs et moteurs","Des récepteurs sensoriels","Des muscles et des glandes"]'::jsonb, 0, 'Les nerfs forment le système nerveux périphérique.', 1),
    ('c8074314-6bdc-51ac-ab8b-dc85362fc182'::uuid, '2bf5052b-68e6-5ee0-a2aa-9f0891c7666a'::uuid, 'Quel est l’ordre du trajet d’un message nerveux ?', 'mcq', '["Récepteur, nerf sensitif, centre nerveux, nerf moteur, effecteur","Effecteur, nerf moteur, centre nerveux, récepteur","Centre nerveux, récepteur, effecteur","Récepteur, effecteur, centre nerveux"]'::jsonb, 0, 'Le centre nerveux traite l’information et élabore la réponse.', 2),
    ('342cb49a-2ab9-59ae-bde6-d4968b70fa7e'::uuid, '2bf5052b-68e6-5ee0-a2aa-9f0891c7666a'::uuid, 'Où se fait le traitement lors d’un réflexe ?', 'mcq', '["Dans la moelle épinière","Dans le cerveau","Dans le nerf sensitif","Dans le muscle lui-même"]'::jsonb, 0, 'Court-circuiter le cerveau rend la réaction beaucoup plus rapide.', 3),
    ('1eb96d7d-8a08-50d3-85a6-c743ca104a5d'::uuid, '2bf5052b-68e6-5ee0-a2aa-9f0891c7666a'::uuid, 'Comment le message franchit-il la synapse ?', 'mcq', '["Grâce à des neurotransmetteurs chimiques","Par un courant électrique direct","Par contact des noyaux","Par diffusion sanguine"]'::jsonb, 0, 'C’est là que la plupart des drogues agissent.', 4),
    ('4e7e141c-4c68-5b0a-94b2-968a5891e110'::uuid, '2bf5052b-68e6-5ee0-a2aa-9f0891c7666a'::uuid, 'Quelles parties du neurone reçoivent le message ?', 'mcq', '["Les dendrites","L’axone","Le corps cellulaire uniquement","La synapse"]'::jsonb, 0, 'L’axone, lui, transmet le message vers la synapse.', 5),
    ('dfe65c9f-b554-5b8c-b55c-635c1451eba8'::uuid, '2bf5052b-68e6-5ee0-a2aa-9f0891c7666a'::uuid, 'Qu’est-ce que la plasticité cérébrale ?', 'mcq', '["La capacité des connexions à se remodeler avec l’apprentissage","La capacité des neurones à se multiplier sans limite","La souplesse des membranes cellulaires","La résistance du crâne aux chocs"]'::jsonb, 0, 'Elle permet l’apprentissage tout au long de la vie.', 6),
    ('17e57a81-441d-53b5-8609-12c6d9d396c2'::uuid, '2bf5052b-68e6-5ee0-a2aa-9f0891c7666a'::uuid, 'Pourquoi l’alcool est-il particulièrement risqué à l’adolescence ?', 'mcq', '["Le cerveau est encore en développement","Le foie est plus gros","Les réflexes sont plus lents","La consommation est autorisée"]'::jsonb, 0, 'Les effets sur le cerveau immature sont durables.', 7),
    ('ea74f0b9-c2d0-57ec-a5cd-97933112091b'::uuid, '2bf5052b-68e6-5ee0-a2aa-9f0891c7666a'::uuid, 'Les cellules ciliées de l’oreille interne détruites par le bruit se régénèrent.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'La perte auditive due au bruit est irréversible.', 8),
    ('f4600f35-cb9b-5b70-828b-c5e530c06c1f'::uuid, '1ef5cdd0-e13d-507e-9094-44c3a49a9fde'::uuid, 'À quoi sert la digestion ?', 'mcq', '["À simplifier les grosses molécules en nutriments assimilables","À stocker les aliments dans l’estomac","À produire de l’énergie directement","À éliminer les déchets du sang"]'::jsonb, 0, 'Les nutriments peuvent alors traverser la paroi intestinale.', 1),
    ('c82e3420-57bf-5fcf-ad5d-d67f0ad3853b'::uuid, '1ef5cdd0-e13d-507e-9094-44c3a49a9fde'::uuid, 'Où se fait l’essentiel de la digestion et de l’absorption ?', 'mcq', '["Dans l’intestin grêle","Dans l’estomac","Dans le gros intestin","Dans la bouche"]'::jsonb, 0, 'Sucs pancréatique, biliaire et intestinal y agissent ensemble.', 2),
    ('0da79792-3ec3-58b2-9244-75c5746b9207'::uuid, '1ef5cdd0-e13d-507e-9094-44c3a49a9fde'::uuid, 'Quelle est la particularité des enzymes digestives ?', 'mcq', '["Chacune est spécifique d’un type de molécule","Elles agissent toutes sur tous les aliments","Elles agissent uniquement dans l’estomac","Elles fragmentent mécaniquement les aliments"]'::jsonb, 0, 'Amylase, protéases et lipases ont chacune leur cible.', 3),
    ('3ce61e93-d089-5c58-b114-1177e1bd81fa'::uuid, '1ef5cdd0-e13d-507e-9094-44c3a49a9fde'::uuid, 'En quoi les protéines sont-elles transformées ?', 'mcq', '["En acides aminés","En glucose","En acides gras","En glycérol"]'::jsonb, 0, 'L’amidon donne du glucose, les lipides des acides gras et du glycérol.', 4),
    ('aae4d576-d925-59b8-aa11-f8a72910602a'::uuid, '1ef5cdd0-e13d-507e-9094-44c3a49a9fde'::uuid, 'Quel est le rôle des fibres alimentaires ?', 'mcq', '["Réguler le transit et nourrir le microbiote","Fournir l’essentiel de l’énergie","Remplacer les protéines","Transporter les vitamines dans le sang"]'::jsonb, 0, 'Elles ne sont pas digérées par nos propres enzymes.', 5),
    ('4e1984b1-e865-5a08-ac17-c71d3994db22'::uuid, '1ef5cdd0-e13d-507e-9094-44c3a49a9fde'::uuid, 'Sur quelle durée l’équilibre alimentaire s’évalue-t-il ?', 'mcq', '["Sur plusieurs jours","Repas par repas","Sur une année","Sur une heure"]'::jsonb, 0, 'Un repas déséquilibré isolé n’a pas d’importance.', 6),
    ('fb012831-cf14-5790-a306-be95b8efdf08'::uuid, '1ef5cdd0-e13d-507e-9094-44c3a49a9fde'::uuid, 'Quelle boisson est indispensable ?', 'mcq', '["L’eau","Le jus de fruits","Le lait","Les boissons sucrées"]'::jsonb, 0, 'Toutes les autres sont facultatives.', 7),
    ('25bc90d9-86a4-5de8-a278-39aec74078ee'::uuid, '1ef5cdd0-e13d-507e-9094-44c3a49a9fde'::uuid, 'Les troubles du comportement alimentaire sont des maladies qui se soignent.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Il faut demander de l’aide, sans attendre.', 8),
    ('a758db46-1d51-5aa5-b117-2cbebf104daa'::uuid, 'a518c3ee-b762-540c-b1de-e4c2d6d3df1c'::uuid, 'Quelle différence entre contamination et infection ?', 'mcq', '["La contamination est l’entrée du micro-organisme, l’infection sa multiplication","La contamination est bactérienne, l’infection virale","La contamination est bénigne, l’infection grave","Les deux termes sont synonymes"]'::jsonb, 0, 'Toute contamination ne débouche pas sur une infection.', 1),
    ('50921d0d-8b99-5a5a-bdf4-7174ed3f19b9'::uuid, 'a518c3ee-b762-540c-b1de-e4c2d6d3df1c'::uuid, 'Qu’est-ce que la phagocytose ?', 'mcq', '["Un globule blanc englobe et digère le micro-organisme","Un anticorps neutralise un antigène","Un lymphocyte détruit une cellule infectée","Une barrière naturelle bloque l’entrée d’un microbe"]'::jsonb, 0, 'C’est une réponse rapide et non spécifique.', 2),
    ('8c2fa110-2fbb-51b5-b784-9f58fba62ad2'::uuid, 'a518c3ee-b762-540c-b1de-e4c2d6d3df1c'::uuid, 'Quels signes caractérisent la réaction inflammatoire ?', 'mcq', '["Rougeur, chaleur, gonflement et douleur","Fièvre uniquement","Toux et éternuements","Fatigue et pâleur"]'::jsonb, 0, 'Elle accompagne la réponse immunitaire innée.', 3),
    ('f3b48714-bcbe-518d-822e-d79fad68360f'::uuid, 'a518c3ee-b762-540c-b1de-e4c2d6d3df1c'::uuid, 'Que fabriquent les lymphocytes B ?', 'mcq', '["Des anticorps","Des phagocytes","Des antigènes","Des cellules infectées"]'::jsonb, 0, 'Les lymphocytes T détruisent les cellules infectées.', 4),
    ('d72ab4dd-6fc7-5392-818f-fc6818e358d6'::uuid, 'a518c3ee-b762-540c-b1de-e4c2d6d3df1c'::uuid, 'Quelle est la propriété essentielle d’un anticorps ?', 'mcq', '["Il ne reconnaît qu’un seul antigène","Il détruit tous les micro-organismes","Il agit immédiatement dès la contamination","Il remplace les phagocytes"]'::jsonb, 0, 'C’est le principe de la spécificité immunitaire.', 5),
    ('e205584f-c9e4-5cb8-a629-76049b9002dd'::uuid, 'a518c3ee-b762-540c-b1de-e4c2d6d3df1c'::uuid, 'Qu’est-ce que la mémoire immunitaire ?', 'mcq', '["Des cellules qui persistent et rendent la réponse plus rapide au second contact","La capacité du corps à oublier une infection","La transmission de l’immunité aux enfants","Le stockage des anticorps dans le foie"]'::jsonb, 0, 'C’est ce qui rend une personne immunisée.', 6),
    ('d23aad27-3224-5430-825d-a61d2746fdac'::uuid, 'a518c3ee-b762-540c-b1de-e4c2d6d3df1c'::uuid, 'Sur quel mécanisme repose la vaccination ?', 'mcq', '["La création d’une mémoire immunitaire sans provoquer la maladie","L’injection directe d’anticorps","La destruction des barrières naturelles","L’élimination du microbiote"]'::jsonb, 0, 'Un rappel entretient cette mémoire.', 7),
    ('b15f0f44-7d24-5cf2-9eff-f25f7f2959d3'::uuid, 'a518c3ee-b762-540c-b1de-e4c2d6d3df1c'::uuid, 'L’immunité collective protège aussi les personnes qui ne peuvent pas être vaccinées.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Le micro-organisme ne circule plus assez pour les atteindre.', 8),
    ('cd4ba80e-a60e-5049-b7fa-dce6d8bc8cca'::uuid, 'cebba3dd-8657-5cbf-98f8-1c611d577ef6'::uuid, 'Quelle différence entre asepsie et antisepsie ?', 'mcq', '["L’asepsie évite l’arrivée des microbes, l’antisepsie élimine ceux déjà présents","L’asepsie concerne la peau, l’antisepsie le matériel","L’asepsie utilise des antibiotiques","Les deux termes sont synonymes"]'::jsonb, 0, 'Stérilisation d’un côté, antiseptique de l’autre.', 1),
    ('2b6cf640-b944-5ba7-b208-74d0b181776b'::uuid, 'cebba3dd-8657-5cbf-98f8-1c611d577ef6'::uuid, 'Contre quoi les antibiotiques sont-ils efficaces ?', 'mcq', '["Contre les bactéries uniquement","Contre les virus uniquement","Contre tous les micro-organismes","Contre les champignons uniquement"]'::jsonb, 0, 'Ils n’ont aucun effet sur une grippe ou un rhume.', 2),
    ('cef94634-376e-5f60-84f0-f520cda651bf'::uuid, 'cebba3dd-8657-5cbf-98f8-1c611d577ef6'::uuid, 'Pourquoi faut-il aller au bout d’un traitement antibiotique ?', 'mcq', '["Arrêter trop tôt laisse survivre les bactéries les plus résistantes","Pour éviter les effets secondaires","Pour renforcer la mémoire immunitaire","Pour ne pas gâcher le médicament"]'::jsonb, 0, 'C’est l’un des mécanismes de l’antibiorésistance.', 3),
    ('f873e2ee-b943-5a50-b654-850208d257c2'::uuid, 'cebba3dd-8657-5cbf-98f8-1c611d577ef6'::uuid, 'Qu’est-ce qu’un antibiogramme ?', 'mcq', '["Un test qui identifie l’antibiotique efficace contre une bactérie donnée","Un vaccin contre les bactéries","Un dosage sanguin d’anticorps","Un examen radiologique"]'::jsonb, 0, 'Il permet de choisir la bonne molécule.', 4),
    ('2aff63b6-b6b4-5979-bbce-2e4ddc60b641'::uuid, 'cebba3dd-8657-5cbf-98f8-1c611d577ef6'::uuid, 'La vaccination agit-elle sur une infection déjà déclarée ?', 'mcq', '["Non, c’est une mesure préventive","Oui, elle guérit l’infection","Oui, si elle est faite le premier jour","Uniquement chez l’enfant"]'::jsonb, 0, 'Elle prépare l’organisme avant la rencontre avec l’agent infectieux.', 5),
    ('da88c1c0-db14-59bd-a66f-72f156a2baa9'::uuid, 'cebba3dd-8657-5cbf-98f8-1c611d577ef6'::uuid, 'Quel moyen protège à la fois des IST et d’une grossesse non désirée ?', 'mcq', '["Le préservatif","La pilule","Le stérilet","L’implant"]'::jsonb, 0, 'Les autres contraceptifs ne protègent pas des infections.', 6),
    ('239320ac-87d5-59b8-9e6f-791b8af55799'::uuid, 'cebba3dd-8657-5cbf-98f8-1c611d577ef6'::uuid, 'Quelle est la particularité du sérum thérapeutique ?', 'mcq', '["Il agit immédiatement mais ne laisse pas de mémoire","Il agit lentement et crée une mémoire durable","Il tue les bactéries comme un antibiotique","Il empêche la contamination"]'::jsonb, 0, 'Il apporte des anticorps déjà formés, en urgence.', 7),
    ('a64f0a7f-fc9e-5786-a0b2-f4259386950e'::uuid, 'cebba3dd-8657-5cbf-98f8-1c611d577ef6'::uuid, 'L’antibiorésistance est classée par l’OMS parmi les grandes menaces sanitaires mondiales.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Un usage excessif sélectionne les bactéries résistantes.', 8),
    ('afaa4b9e-ba86-5342-9c90-f9d0aa8b57bc'::uuid, 'd67ae7a5-fa37-5396-aaaf-0d427fe70f7f'::uuid, 'Qu’est-ce que la puberté ?', 'mcq', '["La période qui rend l’organisme capable de se reproduire","Le début de la croissance","La fin de la croissance osseuse","La première année de la vie"]'::jsonb, 0, 'Elle s’accompagne de transformations physiques et psychologiques.', 1),
    ('068e4da4-3712-59f4-8f1f-96132d226900'::uuid, 'd67ae7a5-fa37-5396-aaaf-0d427fe70f7f'::uuid, 'Quelle glande du cerveau déclenche la puberté ?', 'mcq', '["L’hypophyse","La thyroïde","Le pancréas","La glande surrénale"]'::jsonb, 0, 'Ses hormones activent les testicules ou les ovaires.', 2),
    ('a2b8cd7d-87ca-5e0d-b2fd-e48d0e7d4f31'::uuid, 'd67ae7a5-fa37-5396-aaaf-0d427fe70f7f'::uuid, 'Qu’est-ce qu’une hormone ?', 'mcq', '["Un message chimique produit par une glande et transporté par le sang","Un message nerveux transmis par un nerf","Une cellule reproductrice","Une protéine du muscle"]'::jsonb, 0, 'Elle n’agit que sur les cellules capables de la reconnaître.', 3),
    ('c4792f2e-c973-5772-9b72-76a7440c03b0'::uuid, 'd67ae7a5-fa37-5396-aaaf-0d427fe70f7f'::uuid, 'Comment les testicules produisent-ils les spermatozoïdes ?', 'mcq', '["De façon continue à partir de la puberté","Une fois par mois","Uniquement pendant l’adolescence","Par cycles de 28 jours"]'::jsonb, 0, 'La production dure toute la vie.', 4),
    ('f603e1f1-fa23-5f7b-a71a-ea9813331429'::uuid, 'd67ae7a5-fa37-5396-aaaf-0d427fe70f7f'::uuid, 'Qu’est-ce que l’ovulation ?', 'mcq', '["La libération d’un ovule par un ovaire, environ tous les 28 jours","La formation d’un ovule dans l’utérus","L’élimination de la muqueuse utérine","La fusion de l’ovule et du spermatozoïde"]'::jsonb, 0, 'Elle a lieu au milieu du cycle menstruel.', 5),
    ('0d6642c4-fc7c-5cbd-8a8d-484d04abf5c5'::uuid, 'd67ae7a5-fa37-5396-aaaf-0d427fe70f7f'::uuid, 'Que sont les règles ?', 'mcq', '["L’élimination de la muqueuse utérine en l’absence de fécondation","La libération de l’ovule","Une infection bénigne","Le début de la grossesse"]'::jsonb, 0, 'Elles marquent le premier jour du cycle.', 6),
    ('c42615d6-eb6d-5e11-a065-8cb6ae4188c3'::uuid, 'd67ae7a5-fa37-5396-aaaf-0d427fe70f7f'::uuid, 'Où a lieu la fécondation chez la femme ?', 'mcq', '["Dans une trompe","Dans l’utérus","Dans l’ovaire","Dans le vagin"]'::jsonb, 0, 'L’embryon migre ensuite vers l’utérus.', 7),
    ('435053e2-9e25-518b-bf17-7c1c26326cbc'::uuid, 'd67ae7a5-fa37-5396-aaaf-0d427fe70f7f'::uuid, 'Une grossesse est possible dès la première ovulation, avant même les premières règles.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Les cycles irréguliers du début n’offrent aucune protection.', 8),
    ('070bc2f8-9c30-5228-9cdb-c60d17de2636'::uuid, '44c61d56-f1e2-5db3-9776-6e69e2805ad1'::uuid, 'Où a lieu la fécondation ?', 'mcq', '["Dans une trompe","Dans l’utérus","Dans l’ovaire","Dans le placenta"]'::jsonb, 0, 'La cellule œuf descend ensuite vers l’utérus.', 1),
    ('c1bc524c-6482-5ecf-8bab-1bf8b4dfd284'::uuid, '44c61d56-f1e2-5db3-9776-6e69e2805ad1'::uuid, 'Qu’est-ce que la nidation ?', 'mcq', '["L’implantation de l’embryon dans la muqueuse utérine","La fusion des noyaux des gamètes","La formation du placenta","La première division cellulaire"]'::jsonb, 0, 'Elle a lieu vers le 6e ou 7e jour.', 2),
    ('45861ea2-523b-5aa1-ad60-18f207cc14aa'::uuid, '44c61d56-f1e2-5db3-9776-6e69e2805ad1'::uuid, 'Quelle période met en place tous les organes ?', 'mcq', '["Les huit premières semaines, stade embryonnaire","Le dernier trimestre","Les deux dernières semaines","Le neuvième mois"]'::jsonb, 0, 'C’est aussi la période la plus sensible aux agressions.', 3),
    ('672808d2-a824-5b8a-9225-ff7e960e413f'::uuid, '44c61d56-f1e2-5db3-9776-6e69e2805ad1'::uuid, 'Les sangs de la mère et du fœtus se mélangent-ils ?', 'mcq', '["Non, ils circulent de part et d’autre d’une barrière fine","Oui, complètement","Oui, à partir du sixième mois","Uniquement pendant l’accouchement"]'::jsonb, 0, 'Les échanges se font par diffusion à travers le placenta.', 4),
    ('e936c7ee-a147-5be4-bc66-a20889fdbc01'::uuid, '44c61d56-f1e2-5db3-9776-6e69e2805ad1'::uuid, 'Que passe du placenta vers le fœtus ?', 'mcq', '["Le dioxygène et les nutriments","Le dioxyde de carbone et l’urée","Uniquement de l’eau","Des globules rouges maternels"]'::jsonb, 0, 'Les déchets font le trajet inverse.', 5),
    ('c00e3468-4a41-5c07-b1bd-19c13050b357'::uuid, '44c61d56-f1e2-5db3-9776-6e69e2805ad1'::uuid, 'À quoi sert le liquide amniotique ?', 'mcq', '["À amortir les chocs et maintenir la température du fœtus","À nourrir le fœtus","À oxygéner le sang fœtal","À déclencher l’accouchement"]'::jsonb, 0, 'Le cordon ombilical assure, lui, les échanges.', 6),
    ('c2569775-b596-5c84-a97b-445f91a58cbf'::uuid, '44c61d56-f1e2-5db3-9776-6e69e2805ad1'::uuid, 'Quelle quantité d’alcool est sans risque pendant la grossesse ?', 'mcq', '["Aucune","Un verre par semaine","Un verre par jour","Un verre par mois"]'::jsonb, 0, 'L’alcool traverse le placenta et atteint le fœtus.', 7),
    ('c309b025-d112-54ef-a1e0-8a844cd47c63'::uuid, '44c61d56-f1e2-5db3-9776-6e69e2805ad1'::uuid, 'Le nouveau-né bénéficie quelques mois des anticorps transmis par sa mère.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Son propre système immunitaire prend ensuite le relais.', 8),
    ('7df9296b-e091-5806-aab2-6bb0e38e0edb'::uuid, 'de3389d4-36dd-5617-b250-b427d1c1d456'::uuid, 'Comment la pilule contraceptive agit-elle principalement ?', 'mcq', '["Elle bloque l’ovulation","Elle détruit les spermatozoïdes","Elle empêche la nidation uniquement","Elle ferme les trompes"]'::jsonb, 0, 'C’est une contraception hormonale.', 1),
    ('c651390f-3691-5afc-8ad2-4bf8bf0fdd9f'::uuid, 'de3389d4-36dd-5617-b250-b427d1c1d456'::uuid, 'Quel moyen protège à la fois d’une grossesse et des IST ?', 'mcq', '["Le préservatif","La pilule","L’implant","Le stérilet"]'::jsonb, 0, 'C’est le seul à assurer cette double protection.', 2),
    ('b6affe3b-9511-5a9a-87e1-82af5fed13b5'::uuid, 'de3389d4-36dd-5617-b250-b427d1c1d456'::uuid, 'Que faut-il savoir sur la contraception d’urgence ?', 'mcq', '["Elle s’utilise le plus tôt possible et ne remplace pas une contraception régulière","Elle protège pendant un mois","Elle nécessite toujours une ordonnance","Elle est efficace à 100 %"]'::jsonb, 0, 'Elle est gratuite pour les mineures et délivrée sans ordonnance.', 3),
    ('41b9fb68-217f-5bfb-b8b4-72841de5aa6f'::uuid, 'de3389d4-36dd-5617-b250-b427d1c1d456'::uuid, 'Jusqu’à quel terme l’IVG est-elle possible en France ?', 'mcq', '["14 semaines de grossesse","8 semaines de grossesse","20 semaines de grossesse","6 semaines de grossesse"]'::jsonb, 0, 'Soit 16 semaines d’aménorrhée, avec prise en charge à 100 %.', 4),
    ('da3626e0-5159-5fcb-a9bd-c0bef99d4a53'::uuid, 'de3389d4-36dd-5617-b250-b427d1c1d456'::uuid, 'Qu’est-ce qu’une FIV ?', 'mcq', '["Une fécondation réalisée au laboratoire, suivie d’un transfert d’embryon","Le dépôt de sperme dans l’utérus","Une stimulation hormonale de l’ovulation","Une opération des trompes"]'::jsonb, 0, 'L’ICSI consiste à injecter un seul spermatozoïde dans l’ovule.', 5),
    ('88ed2e4b-26b0-5eef-bfa0-f72cbfc48792'::uuid, 'de3389d4-36dd-5617-b250-b427d1c1d456'::uuid, 'Qu’est-ce que l’insémination artificielle ?', 'mcq', '["Le dépôt du sperme directement dans l’utérus","La fécondation en laboratoire","Le don d’ovocytes","La congélation d’embryons"]'::jsonb, 0, 'Elle est plus simple qu’une fécondation in vitro.', 6),
    ('114b1f67-0bf2-5f8d-824a-60c9f1d3db86'::uuid, 'de3389d4-36dd-5617-b250-b427d1c1d456'::uuid, 'La consultation en centre de santé sexuelle est-elle confidentielle pour un mineur ?', 'mcq', '["Oui, et gratuite","Non, l’accord parental est obligatoire","Oui, mais payante","Uniquement à partir de 16 ans"]'::jsonb, 0, 'Elle permet d’obtenir information et prescription.', 7),
    ('281b19e4-059b-537f-812c-7b875924751a'::uuid, 'de3389d4-36dd-5617-b250-b427d1c1d456'::uuid, 'Les questions éthiques posées par l’assistance médicale à la procréation sont tranchées par la loi de bioéthique.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Le débat démocratique décide, pas la science seule.', 8)
  ) AS v(id, quiz_id, question, kind, options, correct_index, explanation, position)
-- Le quiz doit exister : si le NOT EXISTS ci-dessus a écarté un quiz (une
-- leçon en avait déjà un), ses questions ne partent pas dans le vide.
 WHERE EXISTS (SELECT 1 FROM public.quizzes qz WHERE qz.id = v.quiz_id)
ON CONFLICT (id) DO NOTHING;

-- 5. Sonde finale ----------------------------------------------------------
DO $$
DECLARE
  n_vides integer;
  n_chap  integer;
BEGIN
  SELECT count(*) INTO n_chap FROM public.chapters c
   JOIN public.subjects s ON s.id = c.subject_id
   WHERE s.slug IN ('svt');
  SELECT count(*) INTO n_vides FROM public.subjects s
   WHERE s.slug IN ('svt')
     AND NOT EXISTS (SELECT 1 FROM public.chapters c WHERE c.subject_id = s.id);
  IF n_vides > 0 THEN
    RAISE EXCEPTION 'Migration 303 incomplète : % matiere(s) encore sans chapitre', n_vides;
  END IF;
  RAISE NOTICE 'Migration 303 OK : % chapitres sur les matieres visees.', n_chap;
END $$;
